module benchmark/solution

type Mat = {
  m00: int, m01: int, m02: int,
  m10: int, m11: int, m12: int,
  m20: int, m21: int, m22: int
}

pure func dot(a: int, b: int, c: int, d: int, e: int, f: int) -> int {
  let modulus = 1000000007;
  let first = (a * b) % modulus;
  let second = (c * d) % modulus;
  let third = (e * f) % modulus;
  ((first + second) % modulus + third) % modulus
}

pure func multiply(a: Mat, b: Mat) -> Mat = {
  m00: dot(a.m00, b.m00, a.m01, b.m10, a.m02, b.m20),
  m01: dot(a.m00, b.m01, a.m01, b.m11, a.m02, b.m21),
  m02: dot(a.m00, b.m02, a.m01, b.m12, a.m02, b.m22),
  m10: dot(a.m10, b.m00, a.m11, b.m10, a.m12, b.m20),
  m11: dot(a.m10, b.m01, a.m11, b.m11, a.m12, b.m21),
  m12: dot(a.m10, b.m02, a.m11, b.m12, a.m12, b.m22),
  m20: dot(a.m20, b.m00, a.m21, b.m10, a.m22, b.m20),
  m21: dot(a.m20, b.m01, a.m21, b.m11, a.m22, b.m21),
  m22: dot(a.m20, b.m02, a.m21, b.m12, a.m22, b.m22)
}

pure func identity() -> Mat = {
  m00: 1, m01: 0, m02: 0,
  m10: 0, m11: 1, m12: 0,
  m20: 0, m21: 0, m22: 1
}

pure func transition() -> Mat = {
  m00: 1, m01: 0, m02: 1,
  m10: 1, m11: 1, m12: 0,
  m20: 0, m21: 1, m22: 0
}

pure func matrixPower(base: Mat, exponent: int) -> Mat =
  if exponent == 0 then identity()
  else
    let half = matrixPower(base, exponent / 2) in
    let squared = multiply(half, half) in
    if exponent % 2 == 0 then squared else multiply(squared, base)

pure func countValid(n: int) -> int {
  let powered = matrixPower(transition(), n);
  let modulus = 1000000007;
  ((powered.m00 + powered.m10) % modulus + powered.m20) % modulus
}

export func main() -> () ! {IO} {
  println(show(countValid(1000000000000000000)));
  println(show(countValid(987654321987654321)))
}

