module benchmark/solution

import std/io (println)

type Instr = PUSH(int) | ADD | SUB | MUL | DUP | OVER | SWAP | POP | JMP(int) | JMPZ(int) | JMPGT(int) | HALT

pure func fetch(pc: int, prog: [Instr]) -> Instr =
  match prog {
    instr :: rest => if pc == 0 then instr else fetch(pc - 1, rest),
    [] => HALT
  }

pure func execute(pc: int, stack: [int], steps: int, prog: [Instr]) -> ([int], int) =
  match fetch(pc, prog) {
    PUSH(k) => execute(pc + 1, k :: stack, steps + 1, prog),
    ADD => match stack {
      b :: a :: rest => execute(pc + 1, (a + b) :: rest, steps + 1, prog),
      _ => execute(pc + 1, stack, steps + 1, prog)
    },
    SUB => match stack {
      b :: a :: rest => execute(pc + 1, (a - b) :: rest, steps + 1, prog),
      _ => execute(pc + 1, stack, steps + 1, prog)
    },
    MUL => match stack {
      b :: a :: rest => execute(pc + 1, (a * b) :: rest, steps + 1, prog),
      _ => execute(pc + 1, stack, steps + 1, prog)
    },
    DUP => match stack {
      a :: rest => execute(pc + 1, a :: a :: rest, steps + 1, prog),
      _ => execute(pc + 1, stack, steps + 1, prog)
    },
    OVER => match stack {
      b :: a :: rest => execute(pc + 1, a :: b :: a :: rest, steps + 1, prog),
      _ => execute(pc + 1, stack, steps + 1, prog)
    },
    SWAP => match stack {
      b :: a :: rest => execute(pc + 1, a :: b :: rest, steps + 1, prog),
      _ => execute(pc + 1, stack, steps + 1, prog)
    },
    POP => match stack {
      _ :: rest => execute(pc + 1, rest, steps + 1, prog),
      [] => execute(pc + 1, stack, steps + 1, prog)
    },
    JMP(d) => execute(pc + d, stack, steps + 1, prog),
    JMPZ(d) => match stack {
      v :: rest => if v == 0 then execute(pc + d, rest, steps + 1, prog) else execute(pc + 1, rest, steps + 1, prog),
      [] => execute(pc + 1, stack, steps + 1, prog)
    },
    JMPGT(d) => match stack {
      b :: a :: rest => if a > b then execute(pc + d, rest, steps + 1, prog) else execute(pc + 1, rest, steps + 1, prog),
      _ => execute(pc + 1, stack, steps + 1, prog)
    },
    HALT => (stack, steps + 1)
  }

func printStackBottomToTop(xs: [int]) -> () ! {IO} {
  match xs {
    [] => (),
    x :: rest => {
      printStackBottomToTop(rest);
      println(show(x))
    }
  }
}

export func main() -> () ! {IO} {
  let program = [
    PUSH(252),
    PUSH(105),
    OVER,
    OVER,
    SUB,
    JMPZ(12),
    OVER,
    OVER,
    JMPGT(4),
    OVER,
    SUB,
    JMP(-9),
    SWAP,
    OVER,
    SUB,
    SWAP,
    JMP(-14),
    POP,
    HALT
  ];
  let result = execute(0, [], 0, program);
  match result {
    (stack, steps) => {
      printStackBottomToTop(stack);
      println("steps: ${show(steps)}")
    }
  }
}

