import std/list (map, filter, foldl)
import std/option (getOrElse)

export func main() -> () ! {IO, FS, Env} {
  match getArgs() {
    [] => println("Usage: program <filename>"),
    filename :: _ => {
      let content = readFile(filename);
      let lines = filter(\line. not (trim(line) == ""), split(content, "\n"));
      let numbers = map(\line. getOrElse(stringToInt(trim(line)), 0), lines);
      let total = foldl(func(acc: int, x: int) -> int { acc + x }, 0, numbers);
      println(show(total))
    }
  }
}

