import sys
from pathlib import Path

def compute_sum(filepath: Path) -> float:
    total = 0.0
    with filepath.open("r", encoding="utf-8") as f:
        for line in f:
            stripped_line = line.strip()
            if not stripped_line:
                continue
            try:
                total += float(stripped_line)
            except ValueError:
                print(f"Warning: Skipping invalid number '{stripped_line}'", file=sys.stderr)
    return total

def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <filename>", file=sys.stderr)
        sys.exit(1)

    filepath = Path(sys.argv[1])

    if not filepath.is_file():
        print(f"Error: File '{filepath}' not found.", file=sys.stderr)
        sys.exit(1)

    total_sum = compute_sum(filepath)
    print(total_sum)

if __name__ == "__main__":
    main()

