import sys

PUNCT = set("!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~")


def is_ws(c):
    return c is None or c == ' '


def is_punct(c):
    return c is not None and c in PUNCT


class Run:
    __slots__ = ('start', 'orig', 'rem', 'can_open', 'can_close', 'rid')

    def __init__(self, start, orig, can_open, can_close, rid):
        self.start = start
        self.orig = orig
        self.rem = orig
        self.can_open = can_open
        self.can_close = can_close
        self.rid = rid


def parse_runs(line):
    runs = []
    i = 0
    n = len(line)
    rid = 0
    while i < n:
        if line[i] == '*':
            j = i
            while j < n and line[j] == '*':
                j += 1
            length = j - i
            char_after = line[j] if j < n else None
            char_before = line[i - 1] if i > 0 else None

            left = (not is_ws(char_after)) and \
                   (not is_punct(char_after) or is_ws(char_before) or is_punct(char_before))
            right = (not is_ws(char_before)) and \
                    (not is_punct(char_before) or is_ws(char_after) or is_punct(char_after))

            runs.append(Run(i, length, left, right, rid))
            rid += 1
            i = j
        else:
            i += 1
    return runs


def match_runs(runs):
    matches = []
    cursor = 0
    while cursor < len(runs):
        run = runs[cursor]
        if not run.can_close or run.rem == 0:
            cursor += 1
            continue

        closer = run
        opener_idx = None
        for k in range(cursor - 1, -1, -1):
            cand = runs[k]
            if cand.rem == 0 or not cand.can_open:
                continue
            if (closer.can_open or cand.can_close) and \
               (closer.orig + cand.orig) % 3 == 0 and \
               not (closer.orig % 3 == 0 and cand.orig % 3 == 0):
                continue
            opener_idx = k
            break

        if opener_idx is None:
            if not closer.can_open:
                runs.pop(cursor)
            else:
                cursor += 1
            continue

        opener = runs[opener_idx]
        if opener.rem >= 2 and closer.rem >= 2:
            is_strong = True
            opener.rem -= 2
            closer.rem -= 2
        else:
            is_strong = False
            opener.rem -= 1
            closer.rem -= 1

        matches.append((opener.rid, closer.rid, is_strong))

        del runs[opener_idx + 1:cursor]
        closer_new_idx = opener_idx + 1

        if opener.rem == 0:
            runs.pop(opener_idx)
            closer_new_idx -= 1

        if closer.rem == 0:
            runs.pop(closer_new_idx)
            cursor = closer_new_idx
        else:
            cursor = closer_new_idx

    return matches


def render_line(line):
    runs = parse_runs(line)
    original_runs = list(runs)

    matches = match_runs(runs)

    opening = {r.rid: [] for r in original_runs}
    closing = {r.rid: [] for r in original_runs}

    for opener_rid, closer_rid, is_strong in matches:
        tag = 'strong' if is_strong else 'em'
        opening[opener_rid].append(tag)
        closing[closer_rid].append(tag)

    run_by_start = {r.start: r for r in original_runs}

    result = []
    i = 0
    n = len(line)
    while i < n:
        if i in run_by_start:
            r = run_by_start[i]
            for tag in closing[r.rid]:
                result.append(f'</{tag}>')
            result.append('*' * r.rem)
            for tag in reversed(opening[r.rid]):
                result.append(f'<{tag}>')
            i += r.orig
        else:
            result.append(line[i])
            i += 1

    return ''.join(result)


def main():
    for line in sys.stdin:
        line = line.rstrip('\n')
        print(render_line(line))


if __name__ == "__main__":
    main()

