module benchmark/solution

import std/fs (readFile, writeFile)
import std/json (decode, getString, getInt, getStringArrayOrEmpty)
import std/list (length)
import std/string (chars)
import std/result (Ok, Err)
import std/option (Some, None)

pure func countDots(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => (if c == "." then 1 else 0) + countDots(rest)
  }

pure func validateConfig(appName: string, version: string, port: int, features: [string]) -> string =
  if port < 1024 || port > 65535 then "Invalid port"
  else if countDots(chars(version)) != 2 then "Invalid version"
  else if length(features) == 0 then "Invalid features"
  else "Loaded ${appName} v${version} on port ${port} with ${length(features)} features"

func loadAndValidate(path: string) -> string ! {FS} {
  let content = readFile(path);
  match decode(content) {
    Err(_) => "Invalid JSON",
    Ok(config) => match getString(config, "app_name") {
      None => "Invalid app_name",
      Some(appName) => match getString(config, "version") {
        None => "Invalid version",
        Some(version) => match getInt(config, "port") {
          None => "Invalid port",
          Some(port) => {
            let features = getStringArrayOrEmpty(config, "features");
            validateConfig(appName, version, port, features)
          }
        }
      }
    }
  }
}

export func main() -> () ! {IO, FS} {
  let json = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  writeFile("app_config.json", json);
  println(loadAndValidate("app_config.json"))
}

module benchmark/solution

type Tree = Leaf | Node(Tree, int, Tree)

export func insert(tree: Tree, value: int) -> Tree =
  match tree {
    Leaf => Node(Leaf, value, Leaf),
    Node(left, current, right) =>
      if value < current then Node(insert(left, value), current, right)
      else if value > current then Node(left, current, insert(right, value))
      else tree
  }

export func contains(tree: Tree, value: int) -> bool =
  match tree {
    Leaf => false,
    Node(left, current, right) =>
      if value == current then true
      else if value < current then contains(left, value)
      else contains(right, value)
  }

export func size(tree: Tree) -> int =
  match tree {
    Leaf => 0,
    Node(left, _, right) => 1 + size(left) + size(right)
  }

export func isBST(tree: Tree, lower: int, upper: int) -> bool =
  match tree {
    Leaf => true,
    Node(left, value, right) =>
      value > lower &&
      value < upper &&
      isBST(left, lower, value) &&
      isBST(right, value, upper)
  }

export func insertPreservesBST(value: int) -> bool =
  if value <= -999999 || value >= 999999 then true
  else isBST(insert(Leaf, value), -999999, 999999)

export func insertThenFind(value: int) -> bool =
  contains(insert(Leaf, value), value)

export func main() -> () ! {IO} {
  let tree = insert(insert(insert(Leaf, 5), 3), 7);
  println(show(size(tree)));
  println(show(contains(tree, 3)));
  println(show(contains(tree, 4)));
  println(show(isBST(tree, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}

