from __future__ import annotations
from dataclasses import dataclass


@dataclass(frozen=True)
class LeafT:
    pass


@dataclass(frozen=True)
class NodeT:
    value: int
    left: Tree
    right: Tree


Tree = LeafT | NodeT

Leaf = LeafT()


def insert(tree: Tree, x: int) -> Tree:
    match tree:
        case LeafT():
            return NodeT(x, LeafT(), LeafT())
        case NodeT(v, left, right):
            if x < v:
                return NodeT(v, insert(left, x), right)
            elif x > v:
                return NodeT(v, left, insert(right, x))
            else:
                return tree


def size(tree: Tree) -> int:
    match tree:
        case LeafT():
            return 0
        case NodeT(_, left, right):
            return 1 + size(left) + size(right)


def contains(tree: Tree, x: int) -> bool:
    match tree:
        case LeafT():
            return False
        case NodeT(v, left, right):
            if x == v:
                return True
            elif x < v:
                return contains(left, x)
            else:
                return contains(right, x)


def isBST(tree: Tree, lo: int, hi: int) -> bool:
    match tree:
        case LeafT():
            return True
        case NodeT(v, left, right):
            if v <= lo or v >= hi:
                return False
            return isBST(left, lo, v) and isBST(right, v, hi)


def insertPreservesBST(x: int) -> bool:
    tree = insert(insert(insert(Leaf, 5), 3), 7)
    new_tree = insert(tree, x)
    return isBST(new_tree, -999999, 999999)


def insertThenFind(x: int) -> bool:
    tree = insert(Leaf, x)
    return contains(tree, x)


def main():
    print(size(insert(insert(insert(Leaf, 5), 3), 7)))
    print(contains(insert(insert(insert(Leaf, 5), 3), 7), 3))
    print(contains(insert(insert(insert(Leaf, 5), 3), 7), 4))
    print(isBST(insert(insert(insert(Leaf, 5), 3), 7), -999999, 999999))
    print(insertPreservesBST(42))
    print(insertThenFind(42))


if __name__ == "__main__":
    main()

