pure func isDigit(c: string) -> bool =
  charCode(c) >= 48 && charCode(c) <= 57

pure func takeRun(c: string, xs: [string], count: int) -> (int, [string]) =
  match xs {
    [] => (count, []),
    x :: rest => if x == c then takeRun(c, rest, count + 1) else (count, xs)
  }

pure func encodeChars(xs: [string]) -> string =
  match xs {
    [] => "",
    c :: rest => match takeRun(c, rest, 1) {
      (count, remaining) => "${show(count)}${c}${encodeChars(remaining)}"
    }
  }

