from itertools import groupby


def encode(s: str) -> str:
    """Run-length encode: consecutive identical chars -> count + char."""
    return "".join(f"{len(list(group))}{char}" for char, group in groupby(s))


def decode(s: str) -> str:
    """Run-length decode: count + char -> repeated chars. Handles multi-digit counts."""
    result = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        count = int(s[i:j])
        char = s[j]
        result.append(char * count)
        i = j + 1
    return "".join(result)


def roundtrip(s: str) -> bool:
    """Proof that encode then decode returns the original string."""
    return decode(encode(s)) == s


def singleCharEncode(s: str) -> str:
    """Encode a single character."""
    return f"1{s}"


def main() -> None:
    print(encode("aaabbc"))
    print(encode("xyz"))
    print(decode("3a2b1c"))
    print(decode("1x1y1z"))
    print(roundtrip("hello"))
    print(singleCharEncode("q"))


if __name__ == "__main__":
    main()

