def toRoman(n: int) -> str:
    if not 1 <= n <= 3999:
        raise ValueError("integer out of range (1-3999)")
    table = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"),
        (1, "I"),
    ]
    result = []
    for value, symbol in table:
        while n >= value:
            result.append(symbol)
            n -= value
    return "".join(result)


def fromRoman(s: str) -> int:
    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    invalid_chars = set(s) - set(values)
    if invalid_chars:
        raise ValueError(f"invalid characters: {invalid_chars}")
    total = 0
    prev = 0
    for ch in reversed(s):
        v = values[ch]
        if v < prev:
            total -= v
        else:
            total += v
        prev = v
    if toRoman(total) != s:
        raise ValueError("not a valid canonical Roman numeral")
    return total


def roundtrip(n: int) -> bool:
    return fromRoman(toRoman(n)) == n


def distinctEncoding(a: int, b: int) -> bool:
    return toRoman(a) != toRoman(b)


def main() -> None:
    print(toRoman(1994))
    print(toRoman(58))
    print(toRoman(3999))
    print(fromRoman("MCMXCIV"))
    print(fromRoman("LVIII"))
    print(roundtrip(2024))
    print(distinctEncoding(4, 6))


if __name__ == "__main__":
    main()

