class SNil:
    pass


class SCons:
    def __init__(self, head: int, tail):
        self.head = head
        self.tail = tail


def sMerge(a, b):
    if isinstance(a, SNil):
        return b
    if isinstance(b, SNil):
        return a
    if a.head < b.head:
        return SCons(a.head, sMerge(a.tail, b))
    elif a.head > b.head:
        return SCons(b.head, sMerge(a, b.tail))
    else:
        return SCons(a.head, sMerge(a.tail, b.tail))


def sIntersect(a, b):
    if isinstance(a, SNil) or isinstance(b, SNil):
        return SNil()
    if a.head < b.head:
        return sIntersect(a.tail, b)
    elif a.head > b.head:
        return sIntersect(a, b.tail)
    else:
        return SCons(a.head, sIntersect(a.tail, b.tail))


def sLength(s) -> int:
    if isinstance(s, SNil):
        return 0
    return 1 + sLength(s.tail)


def toStr(s) -> str:
    elements = []
    while not isinstance(s, SNil):
        elements.append(str(s.head))
        s = s.tail
    return "{" + ", ".join(elements) + "}"


def isSorted(s) -> bool:
    if isinstance(s, SNil):
        return True
    if isinstance(s.tail, SNil):
        return True
    return s.head < s.tail.head and isSorted(s.tail)


def mergePreservesSorted(a, b) -> bool:
    return isSorted(sMerge(a, b))


def inclusionExclusion(a, b) -> bool:
    merged = sMerge(a, b)
    intersected = sIntersect(a, b)
    return sLength(merged) + sLength(intersected) == sLength(a) + sLength(b)


def main():
    a = SCons(1, SCons(3, SCons(5, SNil())))
    b = SCons(2, SCons(3, SCons(4, SNil())))

    print(toStr(sMerge(a, b)))
    print(toStr(sIntersect(a, b)))
    print(sLength(sMerge(a, b)))
    print(isSorted(sMerge(a, b)))
    print(mergePreservesSorted(a, b))
    print(inclusionExclusion(a, b))


if __name__ == "__main__":
    main()

