from pathlib import Path


def create_csv_file(path: Path, content: str) -> None:
    path.write_text(content, encoding="utf-8")


def parse_csv(path: Path) -> tuple[list[str], list[dict[str, str]]]:
    with path.open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        headers = reader.fieldnames or []
        rows = [row for row in reader]
    return headers, rows


def validate_row(row: dict[str, str]) -> bool:
    try:
        age = int(row.get("age", ""))
    except (ValueError, TypeError):
        return False

    if age <= 0:
        return False

    email = row.get("email", "")
    if "@" not in email:
        return False

    name = row.get("name", "")
    if not name:
        return False

    return True


def build_record(row: dict[str, str]) -> dict[str, object]:
    return {
        "name": row["name"],
        "age": int(row["age"]),
        "email": row["email"],
    }


def write_json(path: Path, data: list[dict[str, object]]) -> None:
    with path.open("w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)
        f.write("\n")


def main() -> None:
    csv_content = (
        "name,age,email\n"
        "Alice,30,alice@example.com\n"
        "Bob,25,bob@example.com\n"
        "Carol,35,carol@example.com\n"
    )

    csv_path = Path("users.csv")
    json_path = Path("users.json")

    create_csv_file(csv_path, csv_content)

    _headers, rows = parse_csv(csv_path)

    valid_records: list[dict[str, object]] = []
    for row in rows:
        if validate_row(row):
            valid_records.append(build_record(row))

