module benchmark/solution

import std/list (sortBy)
import std/option (Option, Some, None)

type Requirement = Requirement(string, int, int)
type PackageVersion = PackageVersion(string, int, [Requirement])
type Assignment = Assignment(string, int)

func findAssignment(name: string, assignments: [Assignment]) -> Option[int] =
  match assignments {
    [] => None,
    Assignment(current, version) :: rest =>
      if current == name then Some(version)
      else findAssignment(name, rest)
  }

func collectCandidates(
  universe: [PackageVersion],
  name: string,
  lo: int,
  hi: int
) -> [PackageVersion] =
  match universe {
    [] => [],
    pkg :: rest => match pkg {
      PackageVersion(current, version, requirements) =>
        if current == name && version >= lo && version <= hi
        then pkg :: collectCandidates(rest, name, lo, hi)
        else collectCandidates(rest, name, lo, hi)
    }
  }

func compareVersionsDescending(a: PackageVersion, b: PackageVersion) -> int =
  match a {
    PackageVersion(_, av, _) => match b {
      PackageVersion(_, bv, _) =>
        if av > bv then -1
        else if av < bv then 1
        else 0
    }
  }

func candidates(
  universe: [PackageVersion],
  name: string,
  lo: int,
  hi: int
) -> [PackageVersion] =
  sortBy(
    compareVersionsDescending,
    collectCandidates(universe, name, lo, hi)
  )

func resolve(
  universe: [PackageVersion],
  worklist: [Requirement],
  assignments: [Assignment]
) -> Option[[Assignment]] =
  match worklist {
    [] => Some(assignments),
    Requirement(name, lo, hi) :: remaining =>
      match findAssignment(name, assignments) {
        Some(version) =>
          if version >= lo && version <= hi
          then resolve(universe, remaining, assignments)
          else None,
        None =>
          tryCandidates(
            universe,
            candidates(universe, name, lo, hi),
            remaining,
            assignments
          )
      }
  }

func tryCandidates(
  universe: [PackageVersion],
  choices: [PackageVersion],
  remaining: [Requirement],
  assignments: [Assignment]
) -> Option[[Assignment]] =
  match choices {
    [] => None,
    PackageVersion(name, version, requirements) :: rest => {
      let result = resolve(
        universe,
        requirements ++ remaining,
        Assignment(name, version) :: assignments
      );
      match result {
        Some(done) => Some(done),
        None => tryCandidates(universe, rest, remaining, assignments)
      }
    }
  }

func requirementsFor(
  universe: [PackageVersion],
  name: string,
  version: int
) -> [Requirement] =
  match universe {
    [] => [],
    PackageVersion(current, currentVersion, requirements) :: rest =>
      if current == name && currentVersion == version
      then requirements
      else requirementsFor(rest, name, version)
  }

func compareAssignments(a: Assignment, b: Assignment) -> int =
  match a {
    Assignment(aname, _) => match b {
      Assignment(bname, _) =>
        if aname < bname then -1
        else if aname > bname then 1
        else 0
    }
  }

func printAssignments(assignments: [Assignment]) -> () ! {IO} =
  match assignments {
    [] => (),
    Assignment(name, version) :: rest => {
      println("${name}=${version}");
      printAssignments(rest)
    }
  }

func printResolution(result: Option[[Assignment]]) -> () ! {IO} =
  match result {
    Some(assignments) => {
      println("resolved");
      printAssignments(sortBy(compareAssignments, assignments))
    },
    None => println("conflict")
  }

func resolveApp(universe: [PackageVersion]) -> Option[[Assignment]] =
  resolve(
    universe,
    requirementsFor(universe, "app", 1),
    [Assignment("app", 1)]
  )

export func main() -> () ! {IO} {
  let universeA = [
    PackageVersion("app", 1, [
      Requirement("lib", 1, 3),
      Requirement("util", 3, 3)
    ]),
    PackageVersion("lib", 3, [
      Requirement("core", 3, 3)
    ]),
    PackageVersion("lib", 2, [
      Requirement("core", 1, 2)
    ]),
    PackageVersion("lib", 1, []),
    PackageVersion("util", 3, [
      Requirement("core", 1, 1)
    ]),
    PackageVersion("core", 3, []),
    PackageVersion("core", 2, []),
    PackageVersion("core", 1, [])
  ];
  let universeB = [
    PackageVersion("app", 1, [
      Requirement("x", 1, 1),
      Requirement("y", 1, 1)
    ]),
    PackageVersion("x", 1, [
      Requirement("core", 1, 1)
    ]),
    PackageVersion("y", 1, [
