from typing import Optional

Req = tuple[str, int, int]
Packages = dict[str, dict[int, list[Req]]]


def resolve(packages: Packages, root: str, root_version: int) -> Optional[dict[str, int]]:
    initial_reqs = list(packages[root][root_version])
    assignment = {root: root_version}
    worklist = list(initial_reqs)
    if _solve(packages, assignment, worklist):
        return assignment
    return None


def _solve(packages: Packages, assignment: dict[str, int], worklist: list[Req]) -> bool:
    if not worklist:
        return True

    req = worklist[0]
    rest = worklist[1:]
    dep_name, lo, hi = req

    if dep_name in assignment:
        v = assignment[dep_name]
        if lo <= v <= hi:
            return _solve(packages, assignment, rest)
        return False

    candidates = [v for v in sorted(packages.get(dep_name, {}).keys(), reverse=True) if lo <= v <= hi]
    for v in candidates:
        assignment[dep_name] = v
        new_reqs = list(packages[dep_name][v])
        new_worklist = new_reqs + rest
        if _solve(packages, assignment, new_worklist):
            return True
        del assignment[dep_name]

    return False


universe_a: Packages = {
    "app": {1: [("lib", 1, 3), ("util", 3, 3)]},
    "lib": {
        3: [("core", 3, 3)],
        2: [("core", 1, 2)],
        1: [],
    },
    "util": {3: [("core", 1, 1)]},
    "core": {3: [], 2: [], 1: []},
}

universe_b: Packages = {
    "app": {1: [("x", 1, 1), ("y", 1, 1)]},
    "x": {1: [("core", 1, 1)]},
    "y": {1: [("core", 2, 2)]},
    "core": {2: [], 1: []},
}


def report(result: Optional[dict[str, int]]) -> None:
    if result is None:
        print("conflict")
    else:
        print("resolved")
        for name in sorted(result.keys()):
            print(f"{name}={result[name]}")


def main() -> None:
    report(resolve(universe_a, "app", 1))
    report(resolve(universe_b, "app", 1))


if __name__ == "__main__":
    main()

