    Err(_) => ""
  }
}

func parseDocxFile(filepath: string) -> [Block] ! {FS} {
  let xml = readDocxEntry(filepath);
  match parse(xml) {
    Ok(doc) => extractBodyBlocks(doc),
    Err(_) => []
  }
}

pure func extractBodyBlocks(root: XmlNode) -> [Block] =
  match findFirst(root, "w:body") {
    Some(body) => parseChildren(getChildren(body)),
    None => []
  }

pure func parseChildren(nodes: [XmlNode]) -> [Block] =
  match nodes {
    [] => [],
    node :: rest => {
      let tag = getTag(node);
      let blocks = if tag == "w:p" then [parseParagraph(node)]
                   else if tag == "w:tbl" then [parseTable(node)]
                   else [];
      blocks ++ parseChildren(rest)
    }
  }

pure func getParagraphText(node: XmlNode) -> string {
  let runs = findAll(node, "w:r");
  collectRunTexts(runs)
}

pure func collectRunTexts(runs: [XmlNode]) -> string =
  match runs {
    [] => "",
    r :: rest => {
      let tNodes = findAll(r, "w:t");
      let tText = collectTeTexts(tNodes);
      "${tText}${collectRunTexts(rest)}"
    }
  }

pure func collectTeTexts(nodes: [XmlNode]) -> string =
  match nodes {
    [] => "",
    n :: rest => "${getText(n)}${collectTeTexts(rest)}"
  }

pure func getHeadingLevel(node: XmlNode) -> int =
  match findFirst(node, "w:pPr") {
    Some(pPr) =>
      match findFirst(pPr, "w:pStyle") {
        Some(styleNode) =>
          match getAttr(styleNode, "w:val") {
            Some(val) =>
              if val == "Heading1" then 1
              else if val == "Heading2" then 2
              else 0,
            None => 0
          },
        None => 0
      },
    None => 0
  }

pure func hasNumPr(node: XmlNode) -> bool =
  match findFirst(node, "w:pPr") {
    Some(pPr) =>
      match findFirst(pPr, "w:numPr") {
        Some(_) => true,
        None => false
      },
    None => false
  }

pure func parseParagraph(node: XmlNode) -> Block {
  let text = getParagraphText(node);
  let level = getHeadingLevel(node);
  let isList = hasNumPr(node);
  if level > 0 then HeadingBlock({text: text, level: level})
  else if isList then ListBlock({items: [text], ordered: false})
  else TextBlock({text: text, style: "", level: 0})
}

pure func parseTable(node: XmlNode) -> Block {
  let rows = findAll(node, "w:tr");
  let parsedRows = mapRows(rows);
  TableBlock({rows: parsedRows, headers: [], caption: ""})
}

pure func mapRows(rows: [XmlNode]) -> [[TableCell]] =
  match rows {
    [] => [],
    r :: rest => {
      let cells = findAll(r, "w:tc");
      let row = mapCells(cells);
      row :: mapRows(rest)
    }
  }

pure func mapCells(cells: [XmlNode]) -> [TableCell] =
  match cells {
    [] => [],
    c :: rest => {
      let text = getParagraphText(c);
      simpleCell(text) :: mapCells(rest)
    }
  }

pure func tagBlock(b: Block) -> string =
  match b {
    HeadingBlock({text: t, level: l}) => "H${intToStr(l)}|${t}",
    TextBlock({text: t, style: _, level: _}) => "P|${t}",
    ListBlock({items: xs, ordered: _}) => "L${intToStr(listLength(xs))}",
    TableBlock({rows: rs, headers: _, caption: _}) => "T${intToStr(listLength(rs))}",
    _ => "X"
  }

func printBlocks(bs: [Block]) -> () ! {IO} =
  match bs {
    [] => (),
    b :: rest => {
      let _ = println(tagBlock(b));
      printBlocks(rest)
    }
  }

export func main() -> () ! {IO, FS} {
  let b64 = readFile("doc_b64.txt");
  match fromBase64(b64) {
    Some(bytes) => {
      let _ = writeFileBytes("sample.docx", bytes);
      let blocks = parseDocxFile("sample.docx");
      let _ = println(intToStr(listLength(blocks)));
      printBlocks(blocks)
    },
    None => println("decode-failed")
  }
}

