type Op = Dep(string, int) | Wd(string, int) | Save | Commit | Restore

type Snapshot = {alice: int, bob: int}

type State = {alice: int, bob: int, stack: [Snapshot], failures: int}

pure func applyOp(st: State, op: Op) -> State =
  match op {
    Dep(acct, amt) =>
      if acct == "alice"
      then {st | alice: st.alice + amt}
      else {st | bob: st.bob + amt},
    Wd(acct, amt) => {
      let bal = if acct == "alice" then st.alice else st.bob;
      if bal >= amt
      then
        if acct == "alice"
        then {st | alice: st.alice - amt}
        else {st | bob: st.bob - amt}
      else
        match st.stack {
          [] => {st | failures: st.failures + 1},
          snap :: rest => {alice: snap.alice, bob: snap.bob, stack: rest, failures: st.failures + 1}
        }
    },
    Save => {st | stack: {alice: st.alice, bob: st.bob} :: st.stack},
    Commit =>
      match st.stack {
        [] => {st | failures: st.failures + 1},
        _ :: rest => {st | stack: rest}
      },
    Restore =>
      match st.stack {
        [] => {st | failures: st.failures + 1},
        snap :: rest => {alice: snap.alice, bob: snap.bob, stack: rest, failures: st.failures}
      }
  }

export func main() -> () ! {IO} {
  let ops = [
    Save,
    Dep("alice", 30),
    Save,
    Wd("bob", 80),
    Wd("alice", 90),
    Save,
    Wd("alice", 50),
    Dep("bob", 25),
    Commit,
    Restore,
    Wd("bob", 75),
    Commit,
    Dep("alice", 5)
  ];
  let initial = {alice: 100, bob: 50, stack: [], failures: 0};
  let final = foldl(func(acc: State, op: Op) -> State { applyOp(acc, op) }, initial, ops);
  println("alice=${show(final.alice)}");
  println("bob=${show(final.bob)}");
  println("failures=${show(final.failures)}")
}

