from dataclasses import dataclass, field
from typing import List, Tuple

Account = str
Balance = int


@dataclass
class Snapshot:
    alice: int
    bob: int


@dataclass
class State:
    alice: int = 100
    bob: int = 50
    snapshots: List[Snapshot] = field(default_factory=list)
    failures: int = 0


def snapshot_of(state: State) -> Snapshot:
    return Snapshot(alice=state.alice, bob=state.bob)


def restore_from(state: State, snap: Snapshot) -> None:
    state.alice = snap.alice
    state.bob = snap.bob


def get_balance(state: State, acct: Account) -> int:
    return state.alice if acct == "alice" else state.bob


def set_balance(state: State, acct: Account, value: int) -> None:
    if acct == "alice":
        state.alice = value
    else:
        state.bob = value


def apply_deposit(state: State, acct: Account, amt: int) -> None:
    set_balance(state, acct, get_balance(state, acct) + amt)


def apply_withdraw(state: State, acct: Account, amt: int) -> None:
    if get_balance(state, acct) >= amt:
        set_balance(state, acct, get_balance(state, acct) - amt)
    else:
        state.failures += 1
        if state.snapshots:
            snap = state.snapshots.pop()
            restore_from(state, snap)


def apply_save(state: State) -> None:
    state.snapshots.append(snapshot_of(state))


def apply_commit(state: State) -> None:
    if state.snapshots:
        state.snapshots.pop()
    else:
        state.failures += 1


def apply_restore(state: State) -> None:
    if state.snapshots:
        snap = state.snapshots.pop()
        restore_from(state, snap)
    else:
        state.failures += 1


OPS: List[Tuple] = [
    ("save",),
    ("dep", "alice", 30),
    ("save",),
    ("wd", "bob", 80),
    ("wd", "alice", 90),
    ("save",),
    ("wd", "alice", 50),
    ("dep", "bob", 25),
    ("commit",),
    ("restore",),
    ("wd", "bob", 75),
    ("commit",),
    ("dep", "alice", 5),
]


def process(ops: List[Tuple]) -> State:
    state = State()
    for op in ops:
        if op[0] == "dep":
            apply_deposit(state, op[1], op[2])
        elif op[0] == "wd":
            apply_withdraw(state, op[1], op[2])
        elif op[0] == "save":
            apply_save(state)
        elif op[0] == "commit":
            apply_commit(state)
        elif op[0] == "restore":
            apply_restore(state)
    return state


def main() -> None:
    state = process(OPS)
    print(f"alice={state.alice}")
    print(f"bob={state.bob}")
    print(f"failures={state.failures}")


if __name__ == "__main__":
    main()

