        case Num(value=v):
            return v
        case Add(left=l, right=r):
            return eval_expr(l) + eval_expr(r)
        case Mul(left=l, right=r):
            return eval_expr(l) * eval_expr(r)
        case _:
            raise TypeError(f"Unknown expression type: {type(expr).__name__}")


