module benchmark/solution

import std/io (println)
import std/list (map, filter, length, foldl, sortBy, reverse, nth, take, drop, any)
import std/string (chars, substring, split, contains, join)
import std/option (Option, Some, None)

-- ==================== PART 1: Stack Machine ====================

type Instr = IPush(int) | ISub | IDup | IOver | ISwap | IPop | IJmp(int) | IJmpz(int) | IJmpgt(int) | IHalt

func prog1() -> [Instr] =
  [IPush(462), IPush(198), IOver, IOver, ISub, IJmpz(12),
   IOver, IOver, IJmpgt(4), IOver, ISub, IJmp(0-9),
   ISwap, IOver, ISub, ISwap, IJmp(0-14), IPop, IHalt]

func getInstr(p: [Instr], i: int) -> Instr =
  match nth(p, i) { Some(x) => x, None => IHalt }

func run1(p: [Instr], pc: int, stack: [int], steps: int) -> ([int], int) {
  let ins = getInstr(p, pc);
  let ns = steps + 1;
  match ins {
    IHalt => (stack, ns),
    IPush(k) => run1(p, pc+1, k :: stack, ns),
    ISub => match stack {
      b :: a :: rest => run1(p, pc+1, (a - b) :: rest, ns),
      _ => (stack, ns)
    },
    IDup => match stack {
      t :: rest => run1(p, pc+1, t :: t :: rest, ns),
      _ => (stack, ns)
    },
    IOver => match stack {
      t :: s :: rest => run1(p, pc+1, s :: t :: s :: rest, ns),
      _ => (stack, ns)
    },
    ISwap => match stack {
      t :: s :: rest => run1(p, pc+1, s :: t :: rest, ns),
      _ => (stack, ns)
    },
    IPop => match stack {
      t :: rest => run1(p, pc+1, rest, ns),
      _ => (stack, ns)
    },
    IJmp(d) => run1(p, pc+d, stack, ns),
    IJmpz(d) => match stack {
      v :: rest => if v == 0 then run1(p, pc+d, rest, ns) else run1(p, pc+1, rest, ns),
      _ => (stack, ns)
    },
    IJmpgt(d) => match stack {
      b :: a :: rest => if a > b then run1(p, pc+d, rest, ns) else run1(p, pc+1, rest, ns),
      _ => (stack, ns)
    }
  }
}

func printStackBottomUp(stack: [int]) -> () ! {IO} = {
  let bottomUp = reverse(stack);
  printList(bottomUp)
}

func printList(xs: [int]) -> () ! {IO} =
  match xs {
    [] => (),
    x :: rest => { println(show(x)); printList(rest) }
  }

func part1() -> () ! {IO} {
  match run1(prog1(), 0, [], 0) {
    (stack, steps) => {
      printStackBottomUp(stack);
      println("steps: ${show(steps)}")
    }
  }
}

-- ==================== PART 2: LFU Cache ====================

type Entry = Entry({key: int, val: int, count: int, lastUsed: int})

func entryKey(e: Entry) -> int = match e { Entry(r) => r.key }
func entryVal(e: Entry) -> int = match e { Entry(r) => r.val }
func entryCount(e: Entry) -> int = match e { Entry(r) => r.count }
func entryLast(e: Entry) -> int = match e { Entry(r) => r.lastUsed }

func findEntry(es: [Entry], k: int) -> Option[Entry] =
  match es {
    [] => None,
    e :: rest => if entryKey(e) == k then Some(e) else findEntry(rest, k)
  }

func removeEntry(es: [Entry], k: int) -> [Entry] =
  match es {
    [] => [],
    e :: rest => if entryKey(e) == k then rest else e :: removeEntry(rest, k)
  }

-- find eviction victim: smallest count, ties by smallest lastUsed
func findVictim(es: [Entry], best: Entry) -> Entry =
  match es {
    [] => best,
    e :: rest => {
      let bc = entryCount(best);
      let ec = entryCount(e);
      let newBest = if ec < bc then e
                    else if ec == bc then (if entryLast(e) < entryLast(best) then e else best)
                    else best;
      findVictim(rest, newBest)
    }
  }

type CacheOp = CGet(int) | CPut(int, int)

func cacheOps() -> [CacheOp] =
  [CPut(11,17), CPut(12,27), CPut(13,37), CGet(11), CPut(14,47), CPut(15,57),
   CGet(13), CGet(14), CGet(15), CGet(11), CPut(14,51), CPut(16,67), CGet(15),
   CGet(16), CGet(16), CPut(17,77), CGet(11), CGet(14), CPut(18,87), CGet(17)]

func runCache(ops: [CacheOp], es: [Entry], ts: int) -> [Entry] ! {IO} =
  match ops {
    [] => es,
    op :: rest => {
      let nts = ts + 1;
      match op {
        CGet(k) => match findEntry(es, k) {
          Some(e) => {
            println(show(entryVal(e)));
            let ne = Entry({key: k, val: entryVal(e), count: entryCount(e)+1, lastUsed: nts});
            let nes = ne :: removeEntry(es, k);
            runCache(rest, nes, nts)
          },
          None => {
            println(show(0-1));
            runCache(rest, es, nts)
          }
        },
        CPut(k, v) => match findEntry(es, k) {
          Some(e) => {
            let ne = Entry({key: k, val: v, count: entryCount(e)+1, lastUsed: nts});
            let nes = ne :: removeEntry(es, k);
            runCache(rest, nes, nts)
          },
          None => {
            let cur = if length(es) >= 3 then {
              match es {
                x :: _ => {
                  let victim = findVictim(es, x);
                  removeEntry(es, entryKey(victim))
                },
                [] => es
              }
            } else es;
            let ne = Entry({key: k, val: v, count: 1, lastUsed: nts});
            runCache(rest, ne :: cur, nts)
          }
        }
      }
    }
  }

func cmpEntry(a: Entry, b: Entry) -> int = entryKey(a) - entryKey(b)

func part2() -> () ! {IO} {
  let final = runCache(cacheOps(), [], 0);
  let sorted = sortBy(cmpEntry, final);
  let parts = map(\e. "${show(entryKey(e))}=${show(entryVal(e))}", sorted);
  println("cache: ${join(",", parts)}")
}

-- ==================== PART 3: Ledger ====================

type Bal = Bal({carol: int, dave: int})

type LOp = Dep(string, int) | Wd(string, int) | Save | Commit | Restore

func ledgerOps() -> [LOp] =
  [Save, Dep("carol", 60), Save, Wd("dave", 160), Wd("carol", 180), Save,
   Wd("carol", 100), Dep("dave", 50), Commit, Restore, Wd("dave", 150), Commit, Dep("carol", 10)]

func getBal(b: Bal, who: string) -> int =
  match b { Bal(r) => if who == "carol" then r.carol else r.dave }

func setBal(b: Bal, who: string, v: int) -> Bal =
  match b { Bal(r) => if who == "carol" then Bal({carol: v, dave: r.dave}) else Bal({carol: r.carol, dave: v}) }

func runLedger(ops: [LOp], bal: Bal, snaps: [Bal], fails: int) -> (Bal, int) =
  match ops {
    [] => (bal, fails),
    op :: rest => match op {
      Dep(a, x) => runLedger(rest, setBal(bal, a, getBal(bal, a) + x), snaps, fails),
      Wd(a, x) => if getBal(bal, a) >= x then
                    runLedger(rest, setBal(bal, a, getBal(bal, a) - x), snaps, fails)
                  else
                    match snaps {
                      s :: srest => runLedger(rest, s, srest, fails + 1),
                      [] => runLedger(rest, bal, snaps, fails + 1)
                    },
      Save => runLedger(rest, bal, bal :: snaps, fails),
      Commit => match snaps {
        s :: srest => runLedger(rest, bal, srest, fails),
        [] => runLedger(rest, bal, snaps, fails + 1)
      },
      Restore => match snaps {
        s :: srest => runLedger(rest, s, srest, fails),
        [] => runLedger(rest, bal, snaps, fails + 1)
      }
    }
  }

