-- ==================== PART 4: Expression Parser ====================

type Tok = TNum(int) | TPlus | TMinus | TMul | TDiv | TPow | TLParen | TRParen

func isDigitC(c: string) -> bool =
  c == "0" || c == "1" || c == "2" || c == "3" || c == "4" ||
  c == "5" || c == "6" || c == "7" || c == "8" || c == "9"

func digitVal(c: string) -> int =
  if c == "0" then 0 else if c == "1" then 1 else if c == "2" then 2
  else if c == "3" then 3 else if c == "4" then 4 else if c == "5" then 5
  else if c == "6" then 6 else if c == "7" then 7 else if c == "8" then 8 else 9

func tokenize(cs: [string]) -> [Tok] =
  match cs {
    [] => [],
    c :: rest => {
      if isDigitC(c) then {
        match readNum(cs, 0) {
          (n, remain) => TNum(n) :: tokenize(remain)
        }
      } else if c == "+" then TPlus :: tokenize(rest)
      else if c == "-" then TMinus :: tokenize(rest)
      else if c == "*" then TMul :: tokenize(rest)
      else if c == "/" then TDiv :: tokenize(rest)
      else if c == "^" then TPow :: tokenize(rest)
      else if c == "(" then TLParen :: tokenize(rest)
      else if c == ")" then TRParen :: tokenize(rest)
      else tokenize(rest)
    }
  }

func readNum(cs: [string], acc: int) -> (int, [string]) =
  match cs {
    [] => (acc, []),
    c :: rest => if isDigitC(c) then readNum(rest, acc * 10 + digitVal(c)) else (acc, cs)
  }

type Ast = ANum(int) | ABin(string, Ast, Ast) | AUnary(Ast)

-- Parser: recursive descent
-- level 1: + -  (left)
-- level 2: * /  (left)
-- level 3: unary minus (tighter than */ but looser than ^)
-- level 4: ^ (right)

func parseAddExpr(ts: [Tok]) -> (Ast, [Tok]) =
  match parseMulExpr(ts) {
    (left, rest) => parseAddRest(left, rest)
  }

func parseAddRest(left: Ast, ts: [Tok]) -> (Ast, [Tok]) =
  match ts {
    TPlus :: rest => match parseMulExpr(rest) { (r, rem) => parseAddRest(ABin("+", left, r), rem) },
    TMinus :: rest => match parseMulExpr(rest) { (r, rem) => parseAddRest(ABin("-", left, r), rem) },
    _ => (left, ts)
  }

func parseMulExpr(ts: [Tok]) -> (Ast, [Tok]) =
  match parseUnaryExpr(ts) {
    (left, rest) => parseMulRest(left, rest)
  }

func parseMulRest(left: Ast, ts: [Tok]) -> (Ast, [Tok]) =
  match ts {
    TMul :: rest => match parseUnaryExpr(rest) { (r, rem) => parseMulRest(ABin("*", left, r), rem) },
    TDiv :: rest => match parseUnaryExpr(rest) { (r, rem) => parseMulRest(ABin("/", left, r), rem) },
    _ => (left, ts)
  }

func parseUnaryExpr(ts: [Tok]) -> (Ast, [Tok]) =
  match ts {
    TMinus :: rest => match parseUnaryExpr(rest) { (r, rem) => (AUnary(r), rem) },
    _ => parsePowExpr(ts)
  }

func parsePowExpr(ts: [Tok]) -> (Ast, [Tok]) =
  match parseAtom(ts) {
    (base, rest) => match rest {
      TPow :: prest => match parseUnaryExpr(prest) { (exp, rem) => (ABin("^", base, exp), rem) },
      _ => (base, rest)
    }
  }

func parseAtom(ts: [Tok]) -> (Ast, [Tok]) =
  match ts {
    TNum(n) :: rest => (ANum(n), rest),
    TLParen :: rest => match parseAddExpr(rest) {
      (e, rem) => match rem {
        TRParen :: r2 => (e, r2),
        _ => (e, rem)
      }
    },
    _ => (ANum(0), ts)
  }

func showAst(a: Ast) -> string =
  match a {
    ANum(n) => show(n),
    ABin(op, l, r) => "(${showAst(l)}${op}${showAst(r)})",
    AUnary(x) => "(-${showAst(x)})"
  }

func parseExpr(s: string) -> string {
  let toks = tokenize(chars(s));
  match parseAddExpr(toks) {
    (ast, _) => showAst(ast)
  }
}

