-- ==================== PART 5: Glob Matcher ====================

func charCode2(c: string) -> int =
  match nth(chars(c), 0) { Some(_) => codeOf(c), None => 0 }

-- Use ordering to compare chars for ranges
func chLE(a: string, b: string) -> bool = a <= b
func chGE(a: string, b: string) -> bool = a >= b

-- match set: given set chars list, and a char; returns bool
-- set chars given as list of single chars, handles ranges by scanning
func matchSet(setChars: [string], c: string, negated: bool) -> bool {
  let inSet = setContains(setChars, c);
  if negated then (not inSet) else inSet
}

func setContains(sc: [string], c: string) -> bool =
  match sc {
    [] => false,
    a :: rest => match rest {
      dash :: rest2 => if dash == "-" then {
        match rest2 {
          b :: rest3 => if (c >= a) && (c <= b) then true else setContains(rest3, c),
          [] => (a == c) || (dash == c)
        }
      } else (if a == c then true else setContains(rest, c)),
      [] => a == c
    }
  }

-- glob match: pattern chars, string chars
func globMatch(pat: [string], str: [string]) -> bool =
  match pat {
    [] => match str { [] => true, _ => false },
    p :: prest => {
      if p == "*" then {
        -- try zero, or consume one non-/ char
        if globMatch(prest, str) then true
        else match str {
          s :: srest => if s == "/" then false else globMatch(pat, srest),
          [] => false
        }
      } else if p == "?" then {
        match str {
          s :: srest => if s == "/" then false else globMatch(prest, srest),
          [] => false
        }
      } else if p == "[" then {
        match str {
          s :: srest => {
            -- parse set until ]
            match parseSet(prest) {
              (setChars, negated, remain) => {
                if s == "/" then {
                  -- / matches only if listed literally (not via negation)
                  if (not negated) && setContains(setChars, "/") then globMatch(remain, srest) else false
                } else {
                  if matchSet(setChars, s, negated) then globMatch(remain, srest) else false
                }
              }
            }
          },
          [] => false
        }
      } else {
        match str {
          s :: srest => if s == p then globMatch(prest, srest) else false,
          [] => false
        }
      }
    }
  }

func parseSet(pat: [string]) -> ([string], bool, [string]) =
  match pat {
    "!" :: rest => match collectSet(rest) { (sc, remain) => (sc, true, remain) },
    _ => match collectSet(pat) { (sc, remain) => (sc, false, remain) }
  }

func collectSet(pat: [string]) -> ([string], [string]) =
  match pat {
    [] => ([], []),
    "]" :: rest => ([], rest),
    c :: rest => match collectSet(rest) { (sc, remain) => (c :: sc, remain) }
  }

