-- ==================== PART 6: IR Optimizer ====================

type Operand = ONum(int) | OVar(string, int)  -- OVar(name, index)

type RawI = RAssign(string, Operand, string, Operand) | RInput(string) | RLit(string, int)

-- We'll represent input program with SSA already computed manually via a builder.
-- Instructions before SSA:
-- k = input; w = input; a = 9; a = a - 9; c = k * a; k = k + c;
-- q = w * 4; e = k * 9; f = e - e; e = e + f; r = e * 1; return r

type Inst6 = InInput(string, int)
           | InLit(string, int, int)
           | InBin(string, int, Operand, string, Operand)

-- Simplification table entry
type SimEntry = SConst(int) | SCopy(string, int) | SOpaque

-- Build SSA: track counts per var. We simulate manually.
-- Assignments in order with their most recent def references.

type PreI = PInput(string) | PLit(string, int) | PBin(string, string, string, string) -- dest, l, op, r

func rawProg() -> [PreI] =
  [PInput("k"), PInput("w"), PLit("a", 9), PBin("a", "a", "-", "9lit"),
   PBin("c", "k", "*", "a"), PBin("k", "k", "+", "c"),
   PBin("q", "w", "*", "4lit"), PBin("e", "k", "*", "9lit"),
   PBin("f", "e", "-", "e"), PBin("e", "e", "+", "f"),
   PBin("r", "e", "*", "1lit"), PBin("__ret", "r", "ret", "r")]

-- We do a manual SSA + simplification because full generality is complex.
-- Since program is fixed, hardcode SSA transformation logic.

-- Approach: maintain env: varname -> current (index). counts: varname -> next index.
-- For each pre-instruction, produce SSA instruction with resolved operand refs.

type MapSI = MSI([(string, int)])  -- var -> current index

func lookupCur(env: [(string, int)], v: string) -> int =
  match env {
    [] => 0-1,
    (k, i) :: rest => if k == v then i else lookupCur(rest, v)
  }

func setCur(env: [(string, int)], v: string, i: int) -> [(string, int)] =
  match env {
    [] => [(v, i)],
    (k, x) :: rest => if k == v then (v, i) :: rest else (k, x) :: setCur(rest, v, i)
  }

func nextCount(counts: [(string, int)], v: string) -> int =
  match counts {
    [] => 0,
    (k, i) :: rest => if k == v then i else nextCount(rest, v)
  }

-- Represent SSA instr: SSAI(destName, destIdx, opl, op, opr) where opl/opr are Operand referencing (name,idx) or literal
type SSAI = SI(string, int, Operand, string, Operand)
          | SIInput(string, int)

-- Convert literal operand tokens like "9lit","4lit","1lit" to ONum, else OVar with lookup
func resolveOperand(env: [(string, int)], tok: string) -> Operand =
  if tok == "9lit" then ONum(9)
  else if tok == "4lit" then ONum(4)
  else if tok == "1lit" then ONum(1)
  else OVar(tok, lookupCur(env, tok))

func buildSSA(prog: [PreI], env: [(string, int)], counts: [(string, int)], acc: [SSAI]) -> ([SSAI], Operand) =
  match prog {
    [] => (reverse(acc), ONum(0)),
    p :: rest => match p {
      PInput(v) => {
        let idx = nextCount(counts, v);
        let ncounts = setCur(counts, v, idx + 1);
        let nenv = setCur(env, v, idx);
        buildSSA(rest, nenv, ncounts, SIInput(v, idx) :: acc)
      },
      PLit(v, k) => {
        let idx = nextCount(counts, v);
        let ncounts = setCur(counts, v, idx + 1);
        let nenv = setCur(env, v, idx);
        buildSSA(rest, nenv, ncounts, SI(v, idx, ONum(k), "lit", ONum(k)) :: acc)
      },
      PBin(dest, l, op, r) => {
        if op == "ret" then {
          let ro = resolveOperand(env, l);
          (reverse(acc), ro)
        } else {
          let lo = resolveOperand(env, l);
          let ro = resolveOperand(env, r);
          let idx = nextCount(counts, dest);
          let ncounts = setCur(counts, dest, idx + 1);
          let nenv = setCur(env, dest, idx);
          buildSSA(rest, nenv, ncounts, SI(dest, idx, lo, op, ro) :: acc)
        }
      }
    }
  }

-- Simplification table: map SSA name key (name#idx) -> SimEntry
func ssaKey(n: string, i: int) -> string = "${n}#${show(i)}"

func lookupSim(tbl: [(string, SimEntry)], key: string) -> Option[SimEntry] =
  match tbl {
    [] => None,
    (k, e) :: rest => if k == key then Some(e) else lookupSim(rest, key)
  }

-- substitute an operand: follow Const/Copy chains
func substOperand(tbl: [(string, SimEntry)], o: Operand) -> Operand =
  match o {
    ONum(n) => ONum(n),
    OVar(name, idx) => {
      let key = ssaKey(name, idx);
      match lookupSim(tbl, key) {
        Some(SConst(k)) => ONum(k),
        Some(SCopy(cn, ci)) => substOperand(tbl, OVar(cn, ci)),
        Some(SOpaque) => OVar(name, idx),
        None => OVar(name, idx)
      }
    }
  }

func operandIsNum(o: Operand) -> bool = match o { ONum(_) => true, _ => false }
func operandNum(o: Operand) -> int = match o { ONum(n) => n, _ => 0 }
func operandSameVar(a: Operand, b: Operand) -> bool =
  match a {
    OVar(n1, i1) => match b { OVar(n2, i2) => (n1 == n2) && (i1 == i2), _ => false },
    _ => false
  }

func computeOp(op: string, a: int, b: int) -> int =
  if op == "+" then a + b
  else if op == "-" then a - b
  else if op == "*" then a * b
  else if op == "/" then (if b == 0 then 0 else a / b)
  else 0

-- Kept instruction record
type KeptI = KI(string, int, Operand, string, Operand)

func keptKey(k: KeptI) -> string = match k { KI(n, i, _, _, _) => ssaKey(n, i) }

-- Process SSA instructions forward, building sim table and kept list
func simplify(ssa: [SSAI], tbl: [(string, SimEntry)], kept: [KeptI]) -> ([(string, SimEntry)], [KeptI]) =
  match ssa {
    [] => (tbl, reverse(kept)),
    inst :: rest => match inst {
      SIInput(v, idx) => {
        let key = ssaKey(v, idx);
        let ntbl = tbl ++ [(key, SOpaque)];
        let nk = KI(v, idx, ONum(0), "input", ONum(0)) :: kept;
        simplify(rest, ntbl, nk)
      },
      SI(v, idx, lo, op, ro) => {
        let key = ssaKey(v, idx);
        if op == "lit" then {
          -- literal assignment -> Const, deleted
          simplify(rest, tbl ++ [(key, SConst(operandNum(lo)))], kept)
        } else {
          let sl = substOperand(tbl, lo);
          let sr = substOperand(tbl, ro);
          -- classify
          if operandIsNum(sl) && operandIsNum(sr) then {
            let cv = computeOp(op, operandNum(sl), operandNum(sr));
            simplify(rest, tbl ++ [(key, SConst(cv))], kept)
          } else if (op == "-") && operandSameVar(sl, sr) then {
            simplify(rest, tbl ++ [(key, SConst(0))], kept)
          } else if (op == "*") && ((operandIsNum(sl) && operandNum(sl) == 0) || (operandIsNum(sr) && operandNum(sr) == 0)) then {
            simplify(rest, tbl ++ [(key, SConst(0))], kept)
          } else if (op == "*") && operandIsNum(sr) && operandNum(sr) == 1 then {
            match sl { OVar(n, i) => simplify(rest, tbl ++ [(key, SCopy(n, i))], kept), _ => simplify(rest, tbl ++ [(key, SConst(operandNum(sl)))], kept) }
          } else if (op == "*") && operandIsNum(sl) && operandNum(sl) == 1 then {
            match sr { OVar(n, i) => simplify(rest, tbl ++ [(key, SCopy(n, i))], kept), _ => simplify(rest, tbl ++ [(key, SConst(operandNum(sr)))], kept) }
          } else if (op == "+") && operandIsNum(sr) && operandNum(sr) == 0 then {
            match sl { OVar(n, i) => simplify(rest, tbl ++ [(key, SCopy(n, i))], kept), _ => simplify(rest, tbl ++ [(key, SConst(operandNum(sl)))], kept) }
          } else if (op == "+") && operandIsNum(sl) && operandNum(sl) == 0 then {
            match sr { OVar(n, i) => simplify(rest, tbl ++ [(key, SCopy(n, i))], kept), _ => simplify(rest, tbl ++ [(key, SConst(operandNum(sr)))], kept) }
          } else if (op == "-") && operandIsNum(sr) && operandNum(sr) == 0 then {
            match sl { OVar(n, i) => simplify(rest, tbl ++ [(key, SCopy(n, i))], kept), _ => simplify(rest, tbl ++ [(key, SConst(operandNum(sl)))], kept) }
          } else {
            -- Opaque, kept
            let ntbl = tbl ++ [(key, SOpaque)];
            let nk = KI(v, idx, sl, op, sr) :: kept;
            simplify(rest, ntbl, nk)
          }
        }
      }
    }
  }

-- DCE: from return operand, transitively find kept instructions
func findKept(kept: [KeptI], key: string) -> Option[KeptI] =
  match kept {
    [] => None,
    k :: rest => if keptKey(k) == key then Some(k) else findKept(rest, key)
  }

func operandKey(o: Operand) -> Option[string] =
  match o { OVar(n, i) => Some(ssaKey(n, i)), _ => None }

-- collect needed keys via worklist
func collectNeeded(kept: [KeptI], worklist: [string], seen: [string]) -> [string] =
  match worklist {
    [] => seen,
    key :: rest => {
      if listContains(seen, key) then collectNeeded(kept, rest, seen)
      else {
        let nseen = key :: seen;
        match findKept(kept, key) {
          Some(KI(_, _, lo, op, ro)) => {
            let deps = operandKeysList([lo, ro]);
            collectNeeded(kept, deps ++ rest, nseen)
          },
          None => collectNeeded(kept, rest, nseen)
        }
      }
    }
  }

func operandKeysList(os: [Operand]) -> [string] =
  match os {
    [] => [],
    o :: rest => match operandKey(o) {
      Some(k) => k :: operandKeysList(rest),
      None => operandKeysList(rest)
    }
  }

func listContains(xs: [string], v: string) -> bool =
  match xs { [] => false, x :: rest => if x == v then true else listContains(rest, v) }

func showOperand(o: Operand) -> string =
  match o {
    ONum(n) => show(n),
    OVar(n, i) => "${n}.${show(i)}"
  }

