-- ==================== PART 7: PRNG ====================

func prngNext(x: int) -> int = (16807 * x) % 2147483647

func genStream(x: int, n: int, acc: [int]) -> [int] =
  if n == 0 then reverse(acc)
  else {
    let nx = prngNext(x);
    genStream(nx, n - 1, nx :: acc)
  }

func cmpDescInt(a: int, b: int) -> int = b - a

func sumMod(xs: [int], m: int, acc: int) -> int =
  match xs { [] => acc, x :: rest => sumMod(rest, m, (acc + x) % m) }

func sumList(xs: [int]) -> int = foldl(func(a: int, x: int) -> int { a + x }, 0, xs)

