-- ==================== PART 10: Dependency Resolver ====================

-- Universe: package -> version -> requirements list
-- requirement: (dep, lo, hi)

type Req = Req(string, int, int)
type PkgVer = PV(string, int, [Req])  -- package, version, requirements

-- Universe as list of PkgVer
func universeA() -> [PkgVer] =
  [PV("app", 11, [Req("lib", 11, 13), Req("util", 13, 13)]),
   PV("lib", 13, [Req("core", 13, 13)]),
   PV("lib", 12, [Req("core", 11, 12)]),
   PV("lib", 11, []),
   PV("util", 13, [Req("core", 11, 11)]),
   PV("core", 13, []),
   PV("core", 12, []),
   PV("core", 11, [])]

func universeB() -> [PkgVer] =
  [PV("app", 11, [Req("x", 11, 11), Req("y", 11, 11)]),
   PV("x", 11, [Req("core", 11, 11)]),
   PV("y", 11, [Req("core", 12, 12)]),
   PV("core", 12, []),
   PV("core", 11, [])]

-- get requirements for (pkg, ver)
func getReqs(univ: [PkgVer], pkg: string, ver: int) -> Option[[Req]] =
  match univ {
    [] => None,
    PV(p, v, rs) :: rest => if p == pkg && v == ver then Some(rs) else getReqs(rest, pkg, ver)
  }

-- available versions of a package in range, HIGHEST first
func availVersions(univ: [PkgVer], pkg: string, lo: int, hi: int) -> [int] {
  let all = collectVersions(univ, pkg, lo, hi);
  sortBy(cmpDescInt, all)
}

func collectVersions(univ: [PkgVer], pkg: string, lo: int, hi: int) -> [int] =
  match univ {
    [] => [],
    PV(p, v, _) :: rest => if p == pkg && v >= lo && v <= hi then v :: collectVersions(rest, pkg, lo, hi) else collectVersions(rest, pkg, lo, hi)
  }

-- assignments: list of (pkg, ver)
func lookupAssign(assigns: [(string, int)], pkg: string) -> Option[int] =
  match assigns {
    [] => None,
    (p, v) :: rest => if p == pkg then Some(v) else lookupAssign(rest, pkg)
  }

-- resolve: worklist of Req, assignments. Returns Option[[(string,int)]]
func resolve(univ: [PkgVer], worklist: [Req], assigns: [(string, int)]) -> Option[[(string, int)]] =
  match worklist {
    [] => Some(assigns),
    Req(dep, lo, hi) :: rest => {
      match lookupAssign(assigns, dep) {
        Some(v) => {
          if v >= lo && v <= hi then resolve(univ, rest, assigns)
          else None
        },
        None => {
          let versions = availVersions(univ, dep, lo, hi);
          tryVersions(univ, dep, versions, rest, assigns)
        }
      }
    }
  }

func tryVersions(univ: [PkgVer], dep: string, versions: [int], rest: [Req], assigns: [(string, int)]) -> Option[[(string, int)]] =
  match versions {
    [] => None,
    v :: vrest => {
      let newAssigns = (dep, v) :: assigns;
      let depReqs = match getReqs(univ, dep, v) { Some(rs) => rs, None => [] };
      let newWorklist = depReqs ++ rest;
      match resolve(univ, newWorklist, newAssigns) {
        Some(result) => Some(result),
        None => tryVersions(univ, dep, vrest, rest, assigns)
      }
    }
  }

func cmpAssign(a: (string, int), b: (string, int)) -> int =
  match a { (pa, _) => match b { (pb, _) => strCompare(pa, pb) } }

func strCompare(a: string, b: string) -> int =
  if a < b then 0-1 else if a > b then 1 else 0

func resolveUniverse(univ: [PkgVer]) -> () ! {IO} {
  let initReqs = match getReqs(univ, "app", 11) { Some(rs) => rs, None => [] };
  let initAssigns = [("app", 11)];
  match resolve(univ, initReqs, initAssigns) {
    Some(assigns) => {
      println("resolved");
      let sorted = sortBy(cmpAssign, assigns);
      printAssigns(sorted)
    },
    None => println("conflict")
  }
}

func printAssigns(xs: [(string, int)]) -> () ! {IO} =
  match xs {
    [] => (),
    (p, v) :: rest => { println("${p}=${show(v)}"); printAssigns(rest) }
  }

func part10() -> () ! {IO} {
  resolveUniverse(universeA());
  resolveUniverse(universeB())
}

