import string
from functools import lru_cache


def part1():
    program = [
        ('PUSH', 462), ('PUSH', 198), ('OVER',), ('OVER',), ('SUB',), ('JMPZ', 12),
        ('OVER',), ('OVER',), ('JMPGT', 4), ('OVER',), ('SUB',), ('JMP', -9),
        ('SWAP',), ('OVER',), ('SUB',), ('SWAP',), ('JMP', -14), ('POP',), ('HALT',)
    ]
    stack = []
    ip = 0
    steps = 0
    while True:
        instr = program[ip]
        steps += 1
        op = instr[0]
        if op == 'PUSH':
            stack.append(instr[1])
            ip += 1
        elif op == 'SUB':
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
            ip += 1
        elif op == 'DUP':
            stack.append(stack[-1])
            ip += 1
        elif op == 'OVER':
            stack.append(stack[-2])
            ip += 1
        elif op == 'SWAP':
            stack[-1], stack[-2] = stack[-2], stack[-1]
            ip += 1
        elif op == 'POP':
            stack.pop()
            ip += 1
        elif op == 'JMP':
            ip = ip + instr[1]
        elif op == 'JMPZ':
            v = stack.pop()
            if v == 0:
                ip = ip + instr[1]
            else:
                ip += 1
        elif op == 'JMPGT':
            b = stack.pop()
            a = stack.pop()
            if a > b:
                ip = ip + instr[1]
            else:
                ip += 1
        elif op == 'HALT':
            break
    out = []
    for v in stack:
        out.append(str(v))
    out.append(f"steps: {steps}")
    print('\n'.join(out))


def part2():
    cache = {}
    capacity = 3
    time = [0]

    def do_get(k):
        time[0] += 1
        if k in cache:
            cache[k][1] += 1
            cache[k][2] = time[0]

    def do_put(k, v):
        time[0] += 1
        if k in cache:
            cache[k][0] = v
            cache[k][1] += 1
            cache[k][2] = time[0]
        else:
            if len(cache) >= capacity:
                evict_key = min(cache.keys(), key=lambda kk: (cache[kk][1], cache[kk][2]))
                del cache[evict_key]
            cache[k] = [v, 1, time[0]]

    ops = [
        ('put', 11, 17), ('put', 12, 27), ('put', 13, 37), ('get', 11, None),
        ('put', 14, 47), ('put', 15, 57), ('get', 13, None), ('get', 14, None),
        ('get', 15, None), ('get', 11, None), ('put', 14, 51), ('put', 16, 67),
        ('get', 15, None), ('get', 16, None), ('get', 16, None), ('put', 17, 77),
        ('get', 11, None), ('get', 14, None), ('put', 18, 87), ('get', 17, None),
    ]
    for op in ops:
        if op[0] == 'get':
            do_get(op[1])
        else:
            do_put(op[1], op[2])
    parts = [f"{k}={cache[k][0]}" for k in sorted(cache.keys())]
    print("cache: " + ",".join(parts))


def part3():
    balances = {'carol': 200, 'dave': 100}
