    failures = [0]

    def dep(a, x):
        balances[a] += x

    def wd(a, x):
        if balances[a] >= x:
            balances[a] -= x
        else:
            failures[0] += 1
            if snapshots:
                snap = snapshots.pop()
                balances.clear()
                balances.update(snap)

