class ExprParser:
    def __init__(self, s):
        self.s = s
        self.i = 0

    def peek(self):
        return self.s[self.i] if self.i < len(self.s) else ''

    def advance(self):
        c = self.s[self.i]
        self.i += 1
        return c

    def parse_addsub(self):
        node = self.parse_muldiv()
        while self.peek() in ('+', '-'):
            op = self.advance()
            rhs = self.parse_muldiv()
            node = f"({node}{op}{rhs})"
        return node

    def parse_muldiv(self):
        node = self.parse_unary()
        while self.peek() in ('*', '/'):
            op = self.advance()
            rhs = self.parse_unary()
            node = f"({node}{op}{rhs})"
        return node

    def parse_unary(self):
        if self.peek() == '-':
            self.advance()
            operand = self.parse_unary()
            return f"(-{operand})"
        return self.parse_power()

    def parse_power(self):
        node = self.parse_primary()
        if self.peek() == '^':
            self.advance()
            rhs = self.parse_unary()
            node = f"({node}^{rhs})"
        return node

    def parse_primary(self):
        if self.peek() == '(':
            self.advance()
            node = self.parse_addsub()
            self.advance()  # ')'
            return node
        else:
            start = self.i
            while self.i < len(self.s) and self.s[self.i].isdigit():
                self.i += 1
            return str(int(self.s[start:self.i]))


