def glob_match(pattern, s):
    tokens = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '*':
            tokens.append(('star',))
            i += 1
        elif c == '?':
            tokens.append(('any1',))
            i += 1
        elif c == '[':
            j = i + 1
            negate = False
            if j < n and pattern[j] == '!':
                negate = True
                j += 1
            items = set()
            while pattern[j] != ']':
                if j + 1 < n and pattern[j + 1] == '-' and j + 2 < n and pattern[j + 2] != ']':
                    lo = pattern[j]
                    hi = pattern[j + 2]
                    for code in range(ord(lo), ord(hi) + 1):
                        items.add(chr(code))
                    j += 3
                else:
                    items.add(pattern[j])
                    j += 1
            tokens.append(('set', negate, items))
            i = j + 1
        else:
            tokens.append(('lit', c))
            i += 1

    def matches_single(t, c):
        if t[0] == 'lit':
            return c == t[1]
        if t[0] == 'any1':
            return c != '/'
        if t[0] == 'set':
            negate, items = t[1], t[2]
            if c == '/':
                if negate:
                    return False
                else:
                    return '/' in items
            in_set = c in items
            if negate:
                return not in_set
            else:
                return in_set
        return False

    m = len(s)
    ntok = len(tokens)
    memo = {}

    def rec(i, j):
        if (i, j) in memo:
            return memo[(i, j)]
        if i == ntok:
            res = (j == m)
        else:
            t = tokens[i]
            if t[0] == 'star':
                res = False
                if rec(i + 1, j):
                    res = True
                elif j < m and s[j] != '/':
                    res = rec(i, j + 1)
            else:
                if j < m and matches_single(t, s[j]):
                    res = rec(i + 1, j + 1)
                else:
                    res = False
        memo[(i, j)] = res
        return res

    return rec(0, 0)


