    counters = {}
    current = {}
    ssa_instrs = []

    for step in steps:
        kind = step[0]
        if kind == 'input':
            var = step[1]
            idx = counters.get(var, 0)
            counters[var] = idx + 1
            ssadst = f"{var}.{idx}"
            current[var] = ssadst
            ssa_instrs.append(('input', ssadst))
        elif kind == 'const':
            var, value = step[1], step[2]
            idx = counters.get(var, 0)
            counters[var] = idx + 1
            ssadst = f"{var}.{idx}"
            current[var] = ssadst
            ssa_instrs.append(('const', ssadst, value))
        elif kind == 'bin':
            var, op, L, R = step[1], step[2], step[3], step[4]

            def resolve(operand):
                if operand[0] == 'var':
                    return ('var', current[operand[1]])
                return operand

            Lr = resolve(L)
            Rr = resolve(R)
            idx = counters.get(var, 0)
            counters[var] = idx + 1
            ssadst = f"{var}.{idx}"
            current[var] = ssadst
            ssa_instrs.append(('bin', ssadst, op, Lr, Rr))

    return_operand = ('var', current[return_var])

    table = {}
    kept_instrs = []

    def substitute(operand):
        if operand[0] == 'lit':
            return operand
        name = operand[1]
        while True:
            if name in table:
                cls = table[name]
                if cls[0] == 'const':
                    return ('lit', cls[1])
                elif cls[0] == 'copy':
                    name = cls[1]
                    continue
                else:
                    return ('var', name)
            else:
                return ('var', name)

    def compute(a, op, b):
        if op == '+':
            return a + b
        if op == '-':
            return a - b
        if op == '*':
            return a * b
        if op == '/':
            return a // b
        raise ValueError(op)

