            kept_instrs.append(('input', ssadst))
        elif kind == 'const':
            ssadst, value = instr[1], instr[2]
            table[ssadst] = ('const', value)
        elif kind == 'bin':
            ssadst, op, L, R = instr[1], instr[2], instr[3], instr[4]
            Ls = substitute(L)
