            if Ls[0] == 'lit' and Rs[0] == 'lit':
                val = compute(Ls[1], op, Rs[1])
                table[ssadst] = ('const', val)
            elif op == '-' and Ls[0] == 'var' and Rs[0] == 'var' and Ls[1] == Rs[1]:
                table[ssadst] = ('const', 0)
            elif op == '*' and (Ls == ('lit', 0) or Rs == ('lit', 0)):
                table[ssadst] = ('const', 0)
            elif op == '*' and (Ls == ('lit', 1) or Rs == ('lit', 1)):
                other = Rs if Ls == ('lit', 1) else Ls
                if other[0] == 'lit':
                    table[ssadst] = ('const', other[1])
