                M[i][j] += 1

    def mat_mult(A, B):
        size = len(A)
        kk = len(B)
        p = len(B[0])
        C = [[0] * p for _ in range(size)]
        for i in range(size):
            Ai = A[i]
            for k2 in range(kk):
                a = Ai[k2]
                if a:
                    Bk = B[k2]
                    Ci = C[i]
                    for j in range(p):
                        Ci[j] = (Ci[j] + a * Bk[j]) % MOD
        return C

    def mat_pow(mat, n):
        size = len(mat)
        result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
        base = [row[:] for row in mat]
        while n > 0:
            if n & 1:
                result = mat_mult(result, base)
            base = mat_mult(base, base)
            n >>= 1
        return result

    def count(n):
        Mp = mat_pow(M, n)
        return sum(Mp[0]) % MOD

