import std/string (chars, contains, charCode)

type SetRange = SRange(int, int)
type PatElem = PStar | PQuestion | PSet(string, [SetRange], bool) | PLit(string)

func parsePat(cs: [string]) -> [PatElem] =
  match cs {
    [] => [],
    "*" :: rest => PStar :: parsePat(rest),
    "?" :: rest => PQuestion :: parsePat(rest),
    "[" :: rest =>
      match parseSet(rest) {
        (elem, remaining) => elem :: parsePat(remaining)
      },
    c :: rest => PLit(c) :: parsePat(rest)
  }

func parseSet(cs: [string]) -> (PatElem, [string]) =
  match cs {
    "!" :: rest =>
      match collectSetMembers(rest, "", []) {
        (explicit, ranges, afterBracket) =>
          (PSet(explicit, ranges, true), afterBracket)
      },
    _ =>
      match collectSetMembers(cs, "", []) {
        (explicit, ranges, afterBracket) =>
          (PSet(explicit, ranges, false), afterBracket)
      }
  }

func collectSetMembers(cs: [string], explicitAcc: string, rangeAcc: [SetRange]) -> (string, [SetRange], [string]) =
  match cs {
    "]" :: rest => (explicitAcc, rangeAcc, rest),
    [] => (explicitAcc, rangeAcc, []),
    c :: rest =>
      match rest {
        "-" :: c2 :: rest2 =>
          collectSetMembers(rest2, explicitAcc, SRange(charCode(c), charCode(c2)) :: rangeAcc),
        _ =>
          collectSetMembers(rest, "${explicitAcc}${c}", rangeAcc)
      }
  }

func charInSet(c: string, explicit: string, ranges: [SetRange]) -> bool =
  contains(explicit, c) || anyInRange(charCode(c), ranges)

func anyInRange(code: int, ranges: [SetRange]) -> bool =
  match ranges {
    [] => false,
    SRange(lo, hi) :: rest => (code >= lo && code <= hi) || anyInRange(code, rest)
  }

func matchPat(pat: [PatElem], text: [string]) -> bool =
  match pat {
    [] => match text { [] => true, _ => false },
    PStar :: restPat =>
      matchStar(restPat, text),
    PQuestion :: restPat =>
      match text {
        [] => false,
        c :: trest => c != "/" && matchPat(restPat, trest)
      },
    PSet(explicit, ranges, negated) :: restPat =>
      match text {
        [] => false,
        c :: trest => {
          let inSet = charInSet(c, explicit, ranges);
          let slashOk = c != "/" || contains(explicit, "/");
          let ok = if negated then not inSet && c != "/" else inSet && slashOk;
          ok && matchPat(restPat, trest)
        }
      },
    PLit(c) :: restPat =>
      match text {
        [] => false,
        c2 :: trest => c == c2 && matchPat(restPat, trest)
      }
  }

func matchStar(restPat: [PatElem], text: [string]) -> bool =
  if matchPat(restPat, text) then true
  else match text {
    [] => false,
    c :: trest =>
      if c == "/" then false
      else matchStar(restPat, trest)
  }

func globMatch(pattern: string, text: string) -> bool =
  matchPat(parsePat(chars(pattern)), chars(text))

