from functools import lru_cache


def parse_pattern(pattern):
    tokens = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '*':
            tokens.append(('STAR', None))
            i += 1
        elif c == '?':
            tokens.append(('Q', None))
            i += 1
        elif c == '[':
            j = i + 1
            negated = False
            if j < n and pattern[j] == '!':
                negated = True
                j += 1
            members = []
            while j < n and pattern[j] != ']':
                if j + 2 < n and pattern[j + 1] == '-' and pattern[j + 2] != ']':
                    members.append(('range', pattern[j], pattern[j + 2]))
                    j += 3
                else:
                    members.append(('single', pattern[j]))
                    j += 1
            tokens.append(('SET', (negated, members)))
            i = j + 1
        else:
            tokens.append(('LIT', c))
            i += 1
    return tokens


def matches(pattern, text):
    tokens = parse_pattern(pattern)
    nt = len(tokens)
    ns = len(text)

    @lru_cache(maxsize=None)
    def go(ti, si):
        if ti == nt:
            return si == ns
        kind, data = tokens[ti]
        if kind == 'LIT':
            return si < ns and text[si] == data and go(ti + 1, si + 1)
        if kind == 'Q':
            return si < ns and text[si] != '/' and go(ti + 1, si + 1)
        if kind == 'STAR':
            if go(ti + 1, si):
                return True
            k = si
            while k < ns and text[k] != '/':
                if go(ti + 1, k + 1):
                    return True
                k += 1
            return False
        if kind == 'SET':
            if si >= ns:
                return False
            ch = text[si]
            negated, members = data
            if negated and ch == '/':
                return False
            in_set = False
            for m in members:
                if m[0] == 'single':
                    if ch == m[1]:
                        in_set = True
                        break
                else:
                    _, lo, hi = m
                    if lo <= ch <= hi:
                        in_set = True
                        break
            matched = (not in_set) if negated else in_set
            return matched and go(ti + 1, si + 1)
        return False

    return go(0, 0)


def main():
    pairs = [
        ("*.txt", "notes.txt"),
        ("*.txt", "dir/notes.txt"),
        ("a*b*c", "axbxbc"),
        ("a*b*c", "axbxbd"),
        ("?at", "cat"),
        ("?at", "/at"),
        ("[a-c]at", "bat"),
        ("[!a-c]at", "bat"),
        ("[!a-c]at", "rat"),
        ("[!/]x", "/x"),
        ("a[/]b", "a/b"),
        ("*", ""),
        ("*x*", "xx"),
        ("*ab", "aab"),
        ("a?c*", "abc"),
        ("*/", "abc/"),
    ]
    for pattern, text in pairs:
        print(1 if matches(pattern, text) else 0)


if __name__ == "__main__":
    main()

