func contains(x: int, xs: [int]) -> bool =
  match xs {
    [] => false,
    y :: rest => if x == y then true else contains(x, rest)
  }

func enqueue(x: int, queue: [int]) -> [int] =
  match queue {
    [] => [x],
    y :: rest => y :: enqueue(x, rest)
  }

func enqueueAll(xs: [int], queue: [int]) -> [int] =
  match xs {
    [] => queue,
    x :: rest => enqueueAll(rest, enqueue(x, queue))
  }

func getNeighbors(node: int, graph: [(int, [int])]) -> [int] =
  match graph {
    [] => [],
    (current, adjacent) :: rest =>
      if node == current then adjacent else getNeighbors(node, rest)
  }

func bfsLoop(graph: [(int, [int])], queue: [int], visited: [int]) -> [int] =
  match queue {
    [] => visited,
    node :: rest =>
      if contains(node, visited) then
        bfsLoop(graph, rest, visited)
      else
        bfsLoop(
          graph,
          enqueueAll(getNeighbors(node, graph), rest),
          enqueue(node, visited)
        )
  }

func bfs(graph: [(int, [int])], start: int) -> [int] =
  bfsLoop(graph, [start], [])

func printNodes(nodes: [int]) -> () ! {IO} =
  match nodes {
    [] => (),
    node :: rest => {
      println(show(node));
      printNodes(rest)
    }
  }

export func main() -> () ! {IO} {
  let graph = [
    (1, [2, 3]),
    (2, [4]),
    (3, [4, 5]),
    (4, []),
    (5, [])
  ];
  printNodes(bfs(graph, 1))
}

