def contains(x, lst):
    """Check if node x is in the list."""
    return x in lst


def enqueue(x, queue):
    """Add x to the end of the queue."""
    queue.append(x)


def bfs(graph, start):
    """Perform BFS on graph starting from start node.

    Returns list of nodes in visit order.
    """
    visited = []
    queue = []

    enqueue(start, queue)

    while queue:
        node = queue.pop(0)

        if not contains(node, visited):
            visited.append(node)

            neighbors = []
            for n, nbrs in graph:
                if n == node:
                    neighbors = nbrs
                    break

            for neighbor in neighbors:
                if not contains(neighbor, visited) and not contains(neighbor, queue):
                    enqueue(neighbor, queue)

    return visited


def main():
    graph = [(1, [2, 3]), (2, [4]), (3, [4, 5]), (4, []), (5, [])]

    result = bfs(graph, 1)

    for node in result:
        print(node)


if __name__ == "__main__":
    main()

