module benchmark/solution

pure func pipe(f: int -> int, g: int -> int) -> int -> int =
  \x. g(f(x))

pure func subtract(x: int, y: int) -> int =
  x - y

pure func negate(x: int) -> int =
  -x

pure func multiply(x: int, y: int) -> int =
  x * y

export func main() -> () ! {IO} {
  let sub4 = \x. subtract(x, 4);
  let double = \x. multiply(2, x);
  let sub4_then_double = pipe(sub4, double);
  let value = sub4_then_double(11);
  println("Result: ${value}")
}

