from functools import partial
from typing import Callable, TypeVar

T = TypeVar("T")
U = TypeVar("U")
V = TypeVar("V")


def pipe(f: Callable[[T], U], g: Callable[[U], V]) -> Callable[[T], V]:
    """Return a function that computes g(f(x)) — apply f first, then g."""
    return lambda x: g(f(x))


def subtract(x: float, y: float) -> float:
    return x - y


def negate(x: float) -> float:
    return -x


def multiply(x: float, y: float) -> float:
    return x * y


sub4: Callable[[float], float] = partial(subtract, y=4)
double: Callable[[float], float] = partial(multiply, 2)

sub4_then_double: Callable[[float], float] = pipe(sub4, double)


def main() -> None:
    result = sub4_then_double(11)
    print(f"Result: {result}")


if __name__ == "__main__":
    main()

