module benchmark/solution

import std/list (sortBy, length)

pure func compareInts(a: int, b: int) -> int =
  if a < b then -1 else if a > b then 1 else 0

pure func valueAtOrZero(xs: [int], index: int) -> int =
  match xs {
    [] => 0,
    x :: rest => if index <= 0 then x else valueAtOrZero(rest, index - 1)
  }

export pure func median(xs: [int]) -> int {
  let sorted = sortBy(compareInts, xs);
  let index = (length(sorted) - 1) / 2;
  valueAtOrZero(sorted, index)
}

export func main() -> () ! {IO} {
  println(show(median([7, 2, 5, 1, 9, 4, 8])));
  println(show(median([10, 20, 30, 40])))
}

