def median(xs: list[int]) -> int:
    if not xs:
        return 0
    sorted_xs = sorted(xs)
    n = len(sorted_xs)
    return sorted_xs[(n - 1) // 2]


def main() -> None:
    print(median([7, 2, 5, 1, 9, 4, 8]))
    print(median([10, 20, 30, 40]))


if __name__ == "__main__":
    main()

