module benchmark/solution

import std/json (Json, decode, asArray, getString, getInt, getNumber)
import std/math (intToFloat, floatToInt)

func formatCents(cents: int) -> string {
  let whole = cents / 100;
  let fraction = cents % 100;
  if fraction < 10 then "${show(whole)}.0${show(fraction)}"
  else "${show(whole)}.${show(fraction)}"
}

func printOrder(order: Json) -> () ! {IO} =
  match getString(order, "item") {
    Some(item) => match getInt(order, "qty") {
      Some(qty) => match getNumber(order, "price") {
        Some(price) => {
          let total = intToFloat(qty) * price;
          let cents = floatToInt(total * 100.0);
          if total > 5.0 then println("${item}: ${formatCents(cents)}") else ()
        },
        None => ()
      },
      None => ()
    },
    None => ()
  }

func printOrders(orders: [Json]) -> () ! {IO} =
  match orders {
    [] => (),
    order :: rest => {
      printOrder(order);
      printOrders(rest)
    }
  }

export func main() -> () ! {IO} {
  let source = "[{\"id\":1,\"item\":\"apple\",\"qty\":5,\"price\":1.50},{\"id\":2,\"item\":\"banana\",\"qty\":3,\"price\":0.75},{\"id\":3,\"item\":\"orange\",\"qty\":8,\"price\":2.00}]";
  match decode(source) {
    Ok(json) => match asArray(json) {
      Some(orders) => printOrders(orders),
      None => ()
    },
    Err(_) => ()
  }
}

module benchmark/solution

import std/io (println)

type Milestone = {
  name: string,
  deadline: int,
  price: int,
  deliveredDay: int,
  paidDay: int,
  cancelled: bool,
  paymentCancelled: bool
}

type BreachNotice = {
  id: string,
  milestone: string,
  kind: string,
  day: int
}

type Termination =
  NoTermination
  | Terminated(int, string)

type ContractState = {
  milestones: [Milestone],
  notices: [BreachNotice],
  waivers: [string],
  termination: Termination
}

type Event =
  DeliverEvent(int, string)
  | AmendEvent(int, string, int)
  | ForceMajeureEvent(int, int, int)
  | PayEvent(int, string)
  | NoticeEvent(int, string, string, string)
  | WaiverEvent(int, string)
  | TerminateEvent(int)

func appendNotice(xs: [BreachNotice], n: BreachNotice) -> [BreachNotice] =
  match xs {
    [] => [n],
    x :: rest => x :: appendNotice(rest, n)
  }

func breachId(name: string, kind: string) -> string =
  "${name}-${kind}"

func isWaived(id: string, waivers: [string]) -> bool =
  match waivers {
    [] => false,
    w :: rest => if w == id then true else isWaived(id, rest)
  }

func isNoticed(id: string, notices: [BreachNotice]) -> bool =
  match notices {
    [] => false,
    n :: rest => if n.id == id then true else isNoticed(id, rest)
  }

func deliverMilestone(ms: [Milestone], name: string, day: int) -> [Milestone] =
  match ms {
    [] => [],
    m :: rest =>
      if m.name == name
      then {m | deliveredDay: day} :: rest
      else m :: deliverMilestone(rest, name, day)
  }

func payMilestone(ms: [Milestone], name: string, day: int) -> [Milestone] =
  match ms {
    [] => [],
    m :: rest =>
      if m.name == name
      then {m | paidDay: day} :: rest
      else m :: payMilestone(rest, name, day)
  }

func amendMilestone(ms: [Milestone], name: string, newPrice: int) -> [Milestone] =
  match ms {
    [] => [],
    m :: rest =>
      if m.name == name
      then {m | price: newPrice} :: rest
      else m :: amendMilestone(rest, name, newPrice)
  }

func applyForceMajeure(ms: [Milestone], d1: int, d2: int) -> [Milestone] =
  match ms {
    [] => [],
    m :: rest => {
      let windowLength = d2 - d1 + 1;
      let affected =
        m.deliveredDay < 0 &&
        m.deadline >= d1 &&
        m.deadline <= d2;
      let updated =
        if affected
        then {m | deadline: m.deadline + windowLength}
        else m;
      updated :: applyForceMajeure(rest, d1, d2)
    }
  }

func actionCures(
  milestone: string,
  kind: string,
  cureEnd: int,
  ms: [Milestone]
) -> bool =
  match ms {
    [] => false,
    m :: rest =>
      if m.name == milestone
      then
        if kind == "delivery"
        then m.deliveredDay >= 0 && m.deliveredDay <= cureEnd
        else m.paidDay >= 0 && m.paidDay <= cureEnd
      else actionCures(milestone, kind, cureEnd, rest)
  }

func noticeIsCured(n: BreachNotice, ms: [Milestone]) -> bool =
  actionCures(n.milestone, n.kind, n.day + 15, ms)

func breachIsCured(
  id: string,
  notices: [BreachNotice],
  ms: [Milestone]
) -> bool =
  match notices {
    [] => false,
    n :: rest =>
      if n.id == id
      then noticeIsCured(n, ms)
      else breachIsCured(id, rest, ms)
  }

func firstTerminationGround(
  notices: [BreachNotice],
  waivers: [string],
  ms: [Milestone],
  day: int
) -> string =
  match notices {
    [] => "",
    n :: rest => {
      let expired = day > n.day + 15;
      let eligible =
        expired &&
        not isWaived(n.id, waivers) &&
        not noticeIsCured(n, ms);
      if eligible
      then n.id
      else firstTerminationGround(rest, waivers, ms, day)
    }
  }

func cancelAtTermination(ms: [Milestone]) -> [Milestone] =
  match ms {
    [] => [],
    m :: rest => {
      let deliveryCancelled = m.deliveredDay < 0;
      let paymentCancelled = deliveryCancelled || m.paidDay < 0;
      let updated = {
        m |
        cancelled: deliveryCancelled,
        paymentCancelled: paymentCancelled
      };
      updated :: cancelAtTermination(rest)
    }
  }

func applyEvent(event: Event, state: ContractState) -> ContractState =
  match event {
    DeliverEvent(day, name) =>
      {state | milestones: deliverMilestone(state.milestones, name, day)},
    AmendEvent(_, name, newPrice) =>
      {state | milestones: amendMilestone(state.milestones, name, newPrice)},
    ForceMajeureEvent(_, d1, d2) =>
      {state | milestones: applyForceMajeure(state.milestones, d1, d2)},
    PayEvent(day, name) =>
      {state | milestones: payMilestone(state.milestones, name, day)},
    NoticeEvent(day, id, milestone, kind) => {
      let notice = {
        id: id,
        milestone: milestone,
        kind: kind,
        day: day
      };
      {state | notices: appendNotice(state.notices, notice)}
    },
    WaiverEvent(_, id) =>
      {state | waivers: id :: state.waivers},
    TerminateEvent(day) => {
      let ground = firstTerminationGround(
        state.notices,
        state.waivers,
        state.milestones,
        day
      );
      if ground == ""
      then state
      else {
        state |
        milestones: cancelAtTermination(state.milestones),
        termination: Terminated(day, ground)
      }
    }
  }

func processEvents(events: [Event], state: ContractState) -> ContractState =
  match events {
    [] => state,
    event :: rest => processEvents(rest, applyEvent(event, state))
  }

func maxZero(n: int) -> int =
  if n < 0 then 0 else n

func cappedPenalty(daysLate: int) -> int = {
  let raw = daysLate * 200;
  if raw > 4000 then 4000 else raw
}

func terminationDay(t: Termination) -> int =
  match t {
    NoTermination => -1,
    Terminated(day, _) => day
  }

func deliveryLateDays(m: Milestone, t: Termination) -> int =
  if m.deliveredDay >= 0
  then maxZero(m.deliveredDay - m.deadline)
  else
    if m.cancelled
    then maxZero(terminationDay(t) - 1 - m.deadline)
    else 0

func deliveryPenalty(m: Milestone, t: Termination) -> int =
  cappedPenalty(deliveryLateDays(m, t))

func paymentLateDays(m: Milestone) -> int =
  if m.paidDay < 0 || m.deliveredDay < 0
  then 0
  else maxZero(m.paidDay - (m.deliveredDay + 10))

func paymentInterest(m: Milestone) -> int = {
  let periods = paymentLateDays(m) / 10;
  (m.price * periods) / 100
}

func vendorOwes(
  ms: [Milestone],
  waivers: [string],
  t: Termination
) -> int =
  match ms {
    [] => 0,
    m :: rest => {
      let id = breachId(m.name, "delivery");
      let amount =
        if isWaived(id, waivers)
        then 0
        else deliveryPenalty(m, t);
      amount + vendorOwes(rest, waivers, t)
    }
  }

func clientOwes(ms: [Milestone], waivers: [string]) -> int =
  match ms {
    [] => 0,
    m :: rest => {
      let id = breachId(m.name, "payment");
      let amount =
        if isWaived(id, waivers)
        then 0
        else paymentInterest(m);
      amount + clientOwes(rest, waivers)
    }
  }

func printEffective(ms: [Milestone]) -> () ! {IO} =
  match ms {
    [] => (),
    m :: rest => {
      println("${m.name} effective: deadline=${m.deadline} price=${m.price}");
      printEffective(rest)
    }
  }

func printDelivery(m: Milestone, t: Termination) -> () ! {IO} = {
  let late = deliveryLateDays(m, t);
  let penalty = deliveryPenalty(m, t);
  if m.deliveredDay >= 0
  then println("${m.name} delivery: DELIVERED day=${m.deliveredDay} late=${late} penalty=${penalty}")
  else println("${m.name} delivery: CANCELLED late_days=${late} penalty=${penalty}")
}

func printPayment(m: Milestone) -> () ! {IO} =
  if m.paymentCancelled
  then println("${m.name} payment: CANCELLED")
  else {
    let late = paymentLateDays(m);
    let interest = paymentInterest(m);
    println("${m.name} payment: PAID day=${m.paidDay} late=${late} interest=${interest}")
  }

func printBreachResolution(
  m: Milestone,
  kind: string,
  notices: [BreachNotice],
  waivers: [string],
  ms: [Milestone]
) -> () ! {IO} = {
  let id = breachId(m.name, kind);
  let waived = isWaived(id, waivers);
  let noticed = isNoticed(id, notices);
  if not waived && not noticed
  then ()
  else
    if waived
    then println("${m.name} ${kind} breach: WAIVED")
    else
      if breachIsCured(id, notices, ms)
      then println("${m.name} ${kind} breach: CURED")
      else println("${m.name} ${kind} breach: UNCURED")
}

func printMilestoneBlocks(
  remaining: [Milestone],
  allMilestones: [Milestone],
  notices: [BreachNotice],
  waivers: [string],
  t: Termination
) -> () ! {IO} =
  match remaining {
    [] => (),
    m :: rest => {
      printDelivery(m, t);
      printPayment(m);
      printBreachResolution(m, "delivery", notices, waivers, allMilestones);
      printBreachResolution(m, "payment", notices, waivers, allMilestones);
      printMilestoneBlocks(rest, allMilestones, notices, waivers, t)
    }
  }

func printTermination(t: Termination) -> () ! {IO} =
  match t {
    NoTermination => (),
    Terminated(day, ground) =>
      println("termination: day=${day} by=Client grounds=${ground}")
  }

func printNet(vendor: int, client: int) -> () ! {IO} =
  if vendor > client
  then println("net: Vendor pays Client ${vendor - client}")
  else
    if client > vendor
    then println("net: Client pays Vendor ${client - vendor}")
    else println("net: settled")

export func main() -> () ! {IO} {
  let contract = [
    {
      name: "M1",
      deadline: 10,
      price: 10000,
      deliveredDay: -1,
      paidDay: -1,
      cancelled: false,
      paymentCancelled: false
    },
    {
      name: "M2",
      deadline: 40,
      price: 20000,
      deliveredDay: -1,
      paidDay: -1,
      cancelled: false,
      paymentCancelled: false
    },
    {
      name: "M3",
      deadline: 70,
      price: 15000,
      deliveredDay: -1,
      paidDay: -1,
      cancelled: false,
      paymentCancelled: false
    }
  ];
  let events = [
    DeliverEvent(8, "M1"),
    AmendEvent(30, "M2", 22000),
    ForceMajeureEvent(35, 38, 44),
    PayEvent(41, "M1"),
    WaiverEvent(45, "M1-payment"),
    DeliverEvent(50, "M2"),
    NoticeEvent(61, "M2-payment", "M2", "payment"),
    PayEvent(74, "M2"),
    NoticeEvent(80, "M3-delivery", "M3", "delivery"),
    TerminateEvent(96)
  ];
  let initialState = {
    milestones: contract,
    notices: [],
    waivers: [],
    termination: NoTermination
  };
  let finalState = processEvents(events, initialState);
  let vendor = vendorOwes(
    finalState.milestones,
    finalState.waivers,
    finalState.termination
  );
  let client = clientOwes(finalState.milestones, finalState.waivers);
  printEffective(finalState.milestones);
  printMilestoneBlocks(
    finalState.milestones,
    finalState.milestones,
    finalState.notices,
    finalState.waivers,
    finalState.termination
  );
  printTermination(finalState.termination);
  println("vendor_owes=${vendor}");
  println("client_owes=${client}");
  printNet(vendor, client)
}

