def main():
    # Initial contract
    deadlines = {"M1": 10, "M2": 40, "M3": 70}
    prices = {"M1": 10000, "M2": 20000, "M3": 15000}

    # State tracking
    delivered = {}
    paid = {}
    notices = []
    waivers = set()
    terminated_day = None
    termination_grounds = None
    cancelled = set()

    # Events in day order
    events = [
        {"day": 8, "type": "deliver", "milestone": "M1"},
        {"day": 30, "type": "amend", "milestone": "M2", "price": 22000},
        {"day": 35, "type": "force_majeure", "d1": 38, "d2": 44},
        {"day": 41, "type": "pay", "milestone": "M1"},
        {"day": 45, "type": "waive", "milestone": "M1", "breach": "payment"},
        {"day": 50, "type": "deliver", "milestone": "M2"},
        {"day": 61, "type": "notice", "milestone": "M2", "breach": "payment"},
        {"day": 74, "type": "pay", "milestone": "M2"},
        {"day": 80, "type": "notice", "milestone": "M3", "breach": "delivery"},
        {"day": 96, "type": "terminate"},
    ]

    for ev in events:
        day = ev["day"]
        etype = ev["type"]

        if etype == "deliver":
            delivered[ev["milestone"]] = day
        elif etype == "amend":
            prices[ev["milestone"]] = ev["price"]
        elif etype == "force_majeure":
            d1 = ev["d1"]
            d2 = ev["d2"]
            window_len = d2 - d1 + 1
            for ms in ["M1", "M2", "M3"]:
                if d1 <= deadlines[ms] <= d2 and ms not in delivered:
                    deadlines[ms] += window_len
        elif etype == "pay":
            paid[ev["milestone"]] = day
        elif etype == "waive":
            waivers.add(f'{ev["milestone"]}-{ev["breach"]}')
        elif etype == "notice":
            notices.append((day, ev["milestone"], ev["breach"]))
        elif etype == "terminate":
            T = day
            valid_ground = None
            for (notice_day, ms, breach_type) in notices:
                breach_id = f"{ms}-{breach_type}"
                cure_end = notice_day + 15
                if T <= cure_end:
                    continue
                if breach_id in waivers:
                    continue
                cured = False
                if breach_type == "payment":
                    if ms in paid and paid[ms] <= cure_end:
                        cured = True
                elif breach_type == "delivery":
                    if ms in delivered and delivered[ms] <= cure_end:
                        cured = True
                if not cured:
                    valid_ground = breach_id
                    break

            if valid_ground is not None:
                terminated_day = T
                termination_grounds = valid_ground
                for ms in ["M1", "M2", "M3"]:
                    if ms not in delivered:
                        cancelled.add(ms)

    # Compute delivery penalties
    delivery_penalty = {}
    delivery_late = {}
    for ms in ["M1", "M2", "M3"]:
        if ms in delivered:
            days_late = max(0, delivered[ms] - deadlines[ms])
            delivery_late[ms] = days_late
            delivery_penalty[ms] = min(days_late * 200, 4000)
        elif ms in cancelled:
            days_late = max(0, (terminated_day - 1) - deadlines[ms])
            delivery_late[ms] = days_late
            delivery_penalty[ms] = min(days_late * 200, 4000)
        else:
            delivery_late[ms] = 0
            delivery_penalty[ms] = 0

    # Compute payment interest
    payment_interest = {}
    payment_late = {}
    for ms in ["M1", "M2", "M3"]:
        if ms in delivered and ms in paid:
            payment_due = delivered[ms] + 10
            days_late = max(0, paid[ms] - payment_due)
            periods = days_late // 10
            interest = (prices[ms] * periods) // 100
            payment_late[ms] = days_late
            payment_interest[ms] = interest
        else:
            payment_late[ms] = 0
            payment_interest[ms] = 0

    # Breach resolutions
    noticed_breaches = set()
    for (_, ms, breach_type) in notices:
        noticed_breaches.add(f"{ms}-{breach_type}")

    all_breach_ids = noticed_breaches | waivers

    breach_resolution = {}
    for breach_id in all_breach_ids:
        ms, btype = breach_id.split("-")
        if breach_id in waivers:
            breach_resolution[breach_id] = "WAIVED"
        else:
            notice_day = None
            for (nd, nms, nbt) in notices:
                if nms == ms and nbt == btype:
                    notice_day = nd
                    break
            if notice_day is None:
                breach_resolution[breach_id] = "WAIVED"
            else:
                cure_end = notice_day + 15
                cured = False
                if btype == "payment":
                    if ms in paid and paid[ms] <= cure_end:
                        cured = True
                elif btype == "delivery":
                    if ms in delivered and delivered[ms] <= cure_end:
                        cured = True
                breach_resolution[breach_id] = "CURED" if cured else "UNCURED"

    # Compute vendor_owes and client_owes
    vendor_owes = 0
    client_owes = 0
    for ms in ["M1", "M2", "M3"]:
        if f"{ms}-delivery" not in waivers:
            vendor_owes += delivery_penalty[ms]
        if f"{ms}-payment" not in waivers:
            client_owes += payment_interest[ms]

    # Output
    for ms in ["M1", "M2", "M3"]:
