import std/list (sortBy, map)
import std/string (join)

type Operation = Get(int) | Put(int, int)
type Entry = Entry(int, int, int, int)
type Lookup = Missing | Present(Entry)

func findEntry(key: int, cache: [Entry]) -> Lookup =
  match cache {
    [] => Missing,
    Entry(k, value, uses, lastUsed) :: rest =>
      if k == key then Present(Entry(k, value, uses, lastUsed))
      else findEntry(key, rest)
  }

func replaceEntry(key: int, replacement: Entry, cache: [Entry]) -> [Entry] =
  match cache {
    [] => [],
    Entry(k, value, uses, lastUsed) :: rest =>
      if k == key then replacement :: rest
      else Entry(k, value, uses, lastUsed) :: replaceEntry(key, replacement, rest)
  }

func removeEntry(key: int, cache: [Entry]) -> [Entry] =
  match cache {
    [] => [],
    Entry(k, value, uses, lastUsed) :: rest =>
      if k == key then rest
      else Entry(k, value, uses, lastUsed) :: removeEntry(key, rest)
  }

func entryCount(cache: [Entry]) -> int =
  match cache {
    [] => 0,
    _ :: rest => 1 + entryCount(rest)
  }

func lessUsed(a: Entry, b: Entry) -> bool =
  match a {
    Entry(_, _, usesA, lastA) =>
      match b {
        Entry(_, _, usesB, lastB) =>
          usesA < usesB || (usesA == usesB && lastA < lastB)
      }
  }

func leastUsed(candidate: Entry, rest: [Entry]) -> Entry =
  match rest {
    [] => candidate,
    entry :: remaining =>
      if lessUsed(entry, candidate) then leastUsed(entry, remaining)
      else leastUsed(candidate, remaining)
  }

func evictOne(cache: [Entry]) -> [Entry] =
  match cache {
    [] => [],
    first :: rest =>
      match leastUsed(first, rest) {
        Entry(key, _, _, _) => removeEntry(key, cache)
      }
  }

func putValue(key: int, value: int, timestamp: int, cache: [Entry]) -> [Entry] =
  match findEntry(key, cache) {
    Present(Entry(_, _, uses, _)) =>
      replaceEntry(key, Entry(key, value, uses + 1, timestamp), cache),
    Missing => {
      let available = if entryCount(cache) == 3 then evictOne(cache) else cache;
      Entry(key, value, 1, timestamp) :: available
    }
  }

func process(operations: [Operation], cache: [Entry], timestamp: int) -> [Entry] ! {IO} =
  match operations {
    [] => cache,
    operation :: rest =>
      match operation {
        Put(key, value) =>
          process(rest, putValue(key, value, timestamp, cache), timestamp + 1),
        Get(key) =>
          match findEntry(key, cache) {
            Missing => {
              println("-1");
              process(rest, cache, timestamp + 1)
            },
            Present(Entry(_, value, uses, _)) => {
              println(show(value));
              let updated = replaceEntry(
                key,
                Entry(key, value, uses + 1, timestamp),
                cache
              );
              process(rest, updated, timestamp + 1)
            }
          }
      }
  }

func compareEntries(a: Entry, b: Entry) -> int =
  match a {
    Entry(keyA, _, _, _) =>
      match b {
        Entry(keyB, _, _, _) => keyA - keyB
      }
  }

func entryText(entry: Entry) -> string =
  match entry {
    Entry(key, value, _, _) => "${key}=${value}"
  }

export func main() -> () ! {IO} {
