    Put(1, 10),
    Put(2, 20),
    Put(3, 30),
    Get(1),
    Put(4, 40),
    Put(5, 50),
    Get(3),
    Get(4),
    Get(5),
    Get(1),
    Put(4, 44),
    Put(6, 60),
    Get(5),
    Get(6),
    Get(6),
    Put(7, 70),
    Get(1),
    Get(4),
    Put(8, 80),
    Get(7)
  ];
  let cache = process(operations, [], 1);
  let sorted = sortBy(compareEntries, cache);
