from pathlib import Path


LOG_CONTENT = """2024-10-29 10:00:00 INFO User logged in: alice
2024-10-29 10:01:15 ERROR Database connection failed
2024-10-29 10:02:30 INFO User logged in: bob
2024-10-29 10:03:45 WARNING High memory usage: 85%
2024-10-29 10:05:00 ERROR API timeout: /users endpoint
2024-10-29 10:06:15 INFO User logged out: alice
"""


def create_log_file(filename: str) -> None:
    Path(filename).write_text(LOG_CONTENT)


def analyze_log(filename: str) -> tuple[dict[str, int], set[str], int]:
    lines = Path(filename).read_text().strip().split("\n")

    level_counts: dict[str, int] = {"INFO": 0, "ERROR": 0, "WARNING": 0}
    users: set[str] = set()

    for line in lines:
        parts = line.split(" ", 3)
        if len(parts) < 4:
            continue
        level = parts[2]
        message = parts[3]

        if level in level_counts:
            level_counts[level] += 1

        if ":" in message:
            after_colon = message.rsplit(":", 1)[1].strip()
            if after_colon.isalpha():
                users.add(after_colon)

    return level_counts, users, len(lines)


def print_results(level_counts: dict[str, int], users: set[str], total: int) -> None:
    print(f"Total log entries: {total}")

    for level in ("INFO", "ERROR", "WARNING"):
        count = level_counts[level]
        percentage = count * 100 // total
        print(f"{level}: {count} ({percentage}%)")

    print(f"Unique users: {', '.join(sorted(users))}")


def main() -> None:
    create_log_file("app.log")
    level_counts, users, total = analyze_log("app.log")
    print_results(level_counts, users, total)


if __name__ == "__main__":
    main()

