module docparse/main

import std/io (println)
import std/fs (readFile)
import std/list (foldl)
import std/string (split, startsWith, trim, substring, length, join, chars)

-- ============================================================
-- Block ADT (docparse/types/document)
-- ============================================================

type Block
  = Heading(int, string)
  | Paragraph(string)
  | CodeBlock(string, string)
  | ListItem(string)
  | BlockQuote(string)
  | HorizontalRule

-- ============================================================
-- Parser state
-- ============================================================

type ParseState = {
  blocks: [Block],
  buffer: [string],
  inCode: bool,
  codeLang: string,
  codeBuffer: [string]
}

export pure func emptyParseState() -> ParseState =
  { blocks: [], buffer: [], inCode: false, codeLang: "", codeBuffer: [] }

pure func countLeadingHashes(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => if c == "#" then 1 + countLeadingHashes(rest) else 0
  }

pure func flushParagraph(state: ParseState) -> ParseState =
  match state.buffer {
    [] => state,
    _ =>
      let text = join("\n", state.buffer) in
      { state | blocks: state.blocks ++ [Paragraph(text)], buffer: [] }
  }

export pure func mdProcessLine(state: ParseState, line: string) -> ParseState =
  if state.inCode then
    if startsWith(trim(line), "```") then
      let codeText = join("\n", state.codeBuffer) in
      { state |
        blocks: state.blocks ++ [CodeBlock(state.codeLang, codeText)],
        codeBuffer: [],
        inCode: false,
        codeLang: ""
      }
    else
      { state | codeBuffer: state.codeBuffer ++ [line] }
  else
    let trimmed = trim(line) in
    if startsWith(trimmed, "```") then
      let lang = trim(substring(trimmed, 3, length(trimmed))) in
      let flushed = flushParagraph(state) in
      { flushed | inCode: true, codeLang: lang, codeBuffer: [] }
    else if startsWith(trimmed, "#") then
      let level = countLeadingHashes(chars(trimmed)) in
      let text = trim(substring(trimmed, level, length(trimmed))) in
      let flushed = flushParagraph(state) in
      { flushed | blocks: flushed.blocks ++ [Heading(level, text)] }
    else if startsWith(trimmed, ">") then
      let text = trim(substring(trimmed, 1, length(trimmed))) in
      let flushed = flushParagraph(state) in
      { flushed | blocks: flushed.blocks ++ [BlockQuote(text)] }
    else if startsWith(trimmed, "- ") || startsWith(trimmed, "* ") then
      let text = trim(substring(trimmed, 2, length(trimmed))) in
      let flushed = flushParagraph(state) in
      { flushed | blocks: flushed.blocks ++ [ListItem(text)] }
    else if trimmed == "---" || trimmed == "***" || trimmed == "___" then
      let flushed = flushParagraph(state) in
      { flushed | blocks: flushed.blocks ++ [HorizontalRule] }
    else if trimmed == "" then
      flushParagraph(state)
    else
      { state | buffer: state.buffer ++ [line] }

export pure func flushState(state: ParseState) -> [Block] =
  let afterCode =
    if state.inCode then
      { state |
        blocks: state.blocks ++ [CodeBlock(state.codeLang, join("\n", state.codeBuffer))],
        inCode: false,
        codeBuffer: []
      }
    else state
  in
  let final = flushParagraph(afterCode) in
  final.blocks

-- ============================================================
-- parseMarkdown: split into lines, fold mdProcessLine, then flush
-- ============================================================

export pure func parseMarkdown(content: string) -> [Block] {
  let lines = split(content, "\n");
  let finalState = foldl(mdProcessLine, emptyParseState(), lines);
  flushState(finalState)
}

-- ============================================================
-- Output formatting
-- ============================================================

pure func blockTag(b: Block) -> string =
  match b {
    Heading(_, _) => "Heading",
    Paragraph(_) => "Paragraph",
    CodeBlock(_, _) => "CodeBlock",
    ListItem(_) => "ListItem",
    BlockQuote(_) => "BlockQuote",
    HorizontalRule => "HorizontalRule"
  }

func printBlocks(blocks: [Block]) -> () ! {IO} =
  match blocks {
    [] => (),
    b :: rest => {
      println(blockTag(b));
      printBlocks(rest)
    }
  }

export func main() -> () ! {IO, FS} {
  let content = readFile("input.md");
  let blocks = parseMarkdown(content);
  printBlocks(blocks)
}

