def split(xs):
    """Split a list into two halves."""
    mid = len(xs) // 2
    return xs[:mid], xs[mid:]


def merge(xs, ys):
    """Merge two sorted lists into one sorted list."""
    result = []
    i = j = 0
    while i < len(xs) and j < len(ys):
        if xs[i] <= ys[j]:
            result.append(xs[i])
            i += 1
        else:
            result.append(ys[j])
            j += 1
    result.extend(xs[i:])
    result.extend(ys[j:])
    return result


def mergeSort(xs):
    """Recursively sort a list using merge sort."""
    if len(xs) <= 1:
        return xs
    left, right = split(xs)
    return merge(mergeSort(left), mergeSort(right))


def main():
    data = [38, 27, 43, 3, 9, 82, 10]
    sorted_data = mergeSort(data)
    print(sorted_data)


if __name__ == "__main__":
