from dataclasses import dataclass
from typing import Union


@dataclass
class Num:
    value: int


@dataclass
class Var:
    name: str


@dataclass
class Add:
    left: "Expr"
    right: "Expr"


@dataclass
class Mul:
    left: "Expr"
    right: "Expr"


@dataclass
class Let:
    name: str
    e1: "Expr"
    e2: "Expr"


Expr = Union[Num, Var, Add, Mul, Let]


def lookup(name: str, env: list[tuple[str, int]]) -> int:
    for n, v in env:
        if n == name:
            return v
    raise NameError(f"Unbound variable: {name}")


def eval(expr: Expr, env: list[tuple[str, int]]) -> int:
    match expr:
        case Num(value):
            return value
        case Var(name):
            return lookup(name, env)
        case Add(left, right):
            return eval(left, env) + eval(right, env)
        case Mul(left, right):
            return eval(left, env) * eval(right, env)
        case Let(name, e1, e2):
            v1 = eval(e1, env)
            return eval(e2, [(name, v1), *env])
    raise TypeError(f"Unknown expression: {expr}")


