type Digits = Digits(string, [string])

func collectDigits(input: [string], acc: string) -> Digits =
  match input {
    [] => Digits(acc, []),
    c :: rest =>
      if c >= "0" && c <= "9"
      then collectDigits(rest, "${acc}${c}")
      else Digits(acc, input)
  }

func parseExpr(input: [string]) -> Parsed =
  parseAdd(input)

func parseAdd(input: [string]) -> Parsed =
  match parseMul(input) {
    Parsed(left, rest) => parseAddRest(left, rest)
  }

func parseAddRest(left: Expr, input: [string]) -> Parsed =
  match input {
    "+" :: rest =>
      match parseMul(rest) {
        Parsed(right, tail) =>
          parseAddRest(Binary("+", left, right), tail)
      },
    "-" :: rest =>
      match parseMul(rest) {
        Parsed(right, tail) =>
          parseAddRest(Binary("-", left, right), tail)
      },
    _ => Parsed(left, input)
  }

func parseMul(input: [string]) -> Parsed =
  match parseUnary(input) {
    Parsed(left, rest) => parseMulRest(left, rest)
