func parseMulRest(left: Expr, input: [string]) -> Parsed =
  match input {
    "*" :: rest =>
      match parseUnary(rest) {
        Parsed(right, tail) =>
          parseMulRest(Binary("*", left, right), tail)
      },
    "/" :: rest =>
      match parseUnary(rest) {
        Parsed(right, tail) =>
          parseMulRest(Binary("/", left, right), tail)
      },
    _ => Parsed(left, input)
  }

func parseUnary(input: [string]) -> Parsed =
