func find_max(tree: Tree) -> int =
  match tree {
    Leaf(v) => v,
    Node(Leaf(lv), v, Leaf(rv)) =>
      if lv >= v && lv >= rv then lv
      else if v >= rv then v
      else rv,
    Node(l, v, r) => {
      let left_max = find_max(l);
      let right_max = find_max(r);
      if v >= left_max && v >= right_max then v
      else if left_max >= right_max then left_max
      else right_max
    }
  }

