module benchmark/solution

import std/list (reverse)
import std/map as M

type Op = Add | Sub | Mul deriving (Eq)

type RawOperand = RName(string) | RLit(int)
type RawExpr = RInput | RLitExpr(int) | RBin(Op, RawOperand, RawOperand)
type RawStmt = RAssign(string, RawExpr) | RRet(string)

type Operand = Name(string) | Num(int)

type SSADef = SInput(string) | SConst(string, int) | SBin(string, Op, Operand, Operand)

type Val = VConst(int) | VCopy(string) | VOpaque

type Kept = KInput(string) | KBin(string, Op, Operand, Operand)

type Simp = CConst(int) | CCopy(string) | CKeep(Kept)

type RenameResult = {defs: [SSADef], ret: string}
type SimpState = {env: Map[string, Val], kept: [Kept]}

pure func opStr(o: Op) -> string =
  match o { Add => "+", Sub => "-", Mul => "*" }

pure func getCount(counts: Map[string, int], v: string) -> int =
  match M.lookup(counts, v) { Some(n) => n, None => 0 }

pure func latestName(latest: Map[string, int], v: string) -> string =
  match M.lookup(latest, v) { Some(i) => "${v}.${show(i)}", None => v }

pure func rawToOpd(latest: Map[string, int], r: RawOperand) -> Operand =
  match r { RName(v) => Name(latestName(latest, v)), RLit(n) => Num(n) }

pure func makeDef(name: string, e: RawExpr, latest: Map[string, int]) -> SSADef =
  match e {
    RInput => SInput(name),
    RLitExpr(n) => SConst(name, n),
    RBin(op, l, r) => SBin(name, op, rawToOpd(latest, l), rawToOpd(latest, r))
  }

pure func renameAcc(stmts: [RawStmt], counts: Map[string, int], latest: Map[string, int], acc: [SSADef]) -> RenameResult =
  match stmts {
    [] => {defs: reverse(acc), ret: ""},
    RRet(v) :: _ => {defs: reverse(acc), ret: latestName(latest, v)},
    RAssign(v, e) :: rest => {
      let k = getCount(counts, v);
      let ssa = "${v}.${show(k)}";
      let counts2 = M.insert(counts, v, k + 1);
      let latest2 = M.insert(latest, v, k);
      let def = makeDef(ssa, e, latest);
      renameAcc(rest, counts2, latest2, def :: acc)
    }
  }

pure func renameProg(stmts: [RawStmt]) -> RenameResult =
  renameAcc(stmts, M.empty(), M.empty(), [])

pure func lookupVal(env: Map[string, Val], x: string) -> Val =
  match M.lookup(env, x) { Some(v) => v, None => VOpaque }

pure func resolveName(env: Map[string, Val], x: string) -> Operand =
  match lookupVal(env, x) {
    VConst(n) => Num(n),
    VCopy(src) => resolveName(env, src),
    VOpaque => Name(x)
  }

pure func resolveOpd(env: Map[string, Val], opd: Operand) -> Operand =
  match opd { Num(n) => Num(n), Name(x) => resolveName(env, x) }

pure func evalOp(op: Op, a: int, b: int) -> int =
  match op { Add => a + b, Sub => a - b, Mul => a * b }

pure func classify(name: string, op: Op, l: Operand, r: Operand) -> Simp =
  match (l, r) {
    (Num(a), Num(b)) => CConst(evalOp(op, a, b)),
    (Name(x), Name(y)) =>
      if x == y && op == Sub then CConst(0) else CKeep(KBin(name, op, l, r)),
    (Num(0), Name(y)) =>
      if op == Mul then CConst(0)
      else if op == Add then CCopy(y)
      else CKeep(KBin(name, op, l, r)),
    (Name(x), Num(0)) =>
      if op == Mul then CConst(0)
      else if op == Sub then CCopy(x)
      else if op == Add then CCopy(x)
      else CKeep(KBin(name, op, l, r)),
    (Num(1), Name(y)) =>
      if op == Mul then CCopy(y) else CKeep(KBin(name, op, l, r)),
    (Name(x), Num(1)) =>
      if op == Mul then CCopy(x) else CKeep(KBin(name, op, l, r)),
    _ => CKeep(KBin(name, op, l, r))
  }

pure func simplifyAcc(defs: [SSADef], env: Map[string, Val], kept: [Kept]) -> SimpState =
  match defs {
    [] => {env: env, kept: reverse(kept)},
    SInput(n) :: rest => simplifyAcc(rest, M.insert(env, n, VOpaque), KInput(n) :: kept),
    SConst(n, v) :: rest => simplifyAcc(rest, M.insert(env, n, VConst(v)), kept),
    SBin(n, op, l, r) :: rest => {
      let sl = resolveOpd(env, l);
      let sr = resolveOpd(env, r);
      let decision = classify(n, op, sl, sr);
      match decision {
        CConst(c) => simplifyAcc(rest, M.insert(env, n, VConst(c)), kept),
        CCopy(src) => simplifyAcc(rest, M.insert(env, n, VCopy(src)), kept),
        CKeep(k) => simplifyAcc(rest, M.insert(env, n, VOpaque), k :: kept)
      }
    }
  }

pure func simplifyProg(defs: [SSADef]) -> SimpState =
  simplifyAcc(defs, M.empty(), [])

pure func member(x: string, xs: [string]) -> bool =
  match xs { [] => false, y :: ys => if x == y then true else member(x, ys) }

pure func addOperandNames(opd: Operand, xs: [string]) -> [string] =
  match opd {
    Num(_) => xs,
    Name(n) => if member(n, xs) then xs else n :: xs
  }

pure func addKeptNames(k: Kept, xs: [string]) -> [string] =
  match k {
    KInput(_) => xs,
    KBin(_, _, l, r) => addOperandNames(r, addOperandNames(l, xs))
  }

pure func defName(k: Kept) -> string =
  match k { KInput(n) => n, KBin(n, _, _, _) => n }

pure func dceRev(rev: [Kept], used: [string], acc: [Kept]) -> [Kept] =
  match rev {
    [] => acc,
    k :: rest =>
      if member(defName(k), used)
        then dceRev(rest, addKeptNames(k, used), k :: acc)
        else dceRev(rest, used, acc)
  }

pure func dce(ret: Operand, kept: [Kept]) -> [Kept] =
  let init = match ret { Num(_) => [], Name(n) => [n] } in
  reverse(dceRev(reverse(kept), init, []))

pure func operandString(o: Operand) -> string =
  match o { Num(n) => show(n), Name(s) => s }

pure func keptString(k: Kept) -> string =
  match k {
    KInput(n) => "${n} = input",
    KBin(n, op, l, r) => "${n} = ${operandString(l)} ${opStr(op)} ${operandString(r)}"
  }

pure func retString(o: Operand) -> string =
  "return ${operandString(o)}"

func printKeptList(ks: [Kept]) -> () ! {IO} =
  match ks {
    [] => (),
    k :: rest => { println(keptString(k)); printKeptList(rest) }
  }

export func main() -> () ! {IO} {
  let program: [RawStmt] = [
    RAssign("n", RInput),
    RAssign("m", RInput),
    RAssign("a", RLitExpr(7)),
    RAssign("a", RBin(Sub, RName("a"), RLit(7))),
    RAssign("c", RBin(Mul, RName("n"), RName("a"))),
    RAssign("n", RBin(Add, RName("n"), RName("c"))),
    RAssign("q", RBin(Mul, RName("m"), RLit(3))),
    RAssign("e", RBin(Mul, RName("n"), RLit(7))),
    RAssign("f", RBin(Sub, RName("e"), RName("e"))),
    RAssign("e", RBin(Add, RName("e"), RName("f"))),
    RAssign("r", RBin(Mul, RName("e"), RLit(1))),
    RRet("r")
  ];
  let ssa = renameProg(program);
  let st = simplifyProg(ssa.defs);
  let retOpd = resolveName(st.env, ssa.ret);
  let surviving = dce(retOpd, st.kept);
  printKeptList(surviving);
  println(retString(retOpd))
}

