from dataclasses import dataclass
from typing import Union


@dataclass
class VarRef:
    name: str


@dataclass
class Lit:
    value: int


Operand = Union[VarRef, Lit]


@dataclass
class InputRHS:
    pass


@dataclass
class LitRHS:
    value: int


@dataclass
class BinOpRHS:
    op: str
    left: Operand
    right: Operand


RHS = Union[InputRHS, LitRHS, BinOpRHS]


@dataclass
class Assign:
    var: str
    rhs: RHS


@dataclass
class Return:
    operand: Operand


Instruction = Union[Assign, Return]


program: list[Instruction] = [
    Assign('n', InputRHS()),
    Assign('m', InputRHS()),
    Assign('a', LitRHS(7)),
    Assign('a', BinOpRHS('-', VarRef('a'), Lit(7))),
    Assign('c', BinOpRHS('*', VarRef('n'), VarRef('a'))),
    Assign('n', BinOpRHS('+', VarRef('n'), VarRef('c'))),
    Assign('q', BinOpRHS('*', VarRef('m'), Lit(3))),
    Assign('e', BinOpRHS('*', VarRef('n'), Lit(7))),
    Assign('f', BinOpRHS('-', VarRef('e'), VarRef('e'))),
    Assign('e', BinOpRHS('+', VarRef('e'), VarRef('f'))),
    Assign('r', BinOpRHS('*', VarRef('e'), Lit(1))),
    Return(VarRef('r')),
]


@dataclass
class Const:
    value: int


@dataclass
class Copy:
    source: str


@dataclass
class Opaque:
    pass


TableValue = Union[Const, Copy, Opaque]


def pass1_ssa(prog: list[Instruction]) -> list[Instruction]:
    counts: dict[str, int] = {}
    current: dict[str, str] = {}
    ssa_program: list[Instruction] = []

    def resolve_operand(operand: Operand) -> Operand:
        if isinstance(operand, VarRef):
            return VarRef(current[operand.name])
        return operand

    for instr in prog:
        if isinstance(instr, Assign):
            if isinstance(instr.rhs, InputRHS):
                new_rhs: RHS = InputRHS()
            elif isinstance(instr.rhs, LitRHS):
                new_rhs = LitRHS(instr.rhs.value)
            else:
                rhs = instr.rhs
                new_lhs = resolve_operand(rhs.left)
                new_right = resolve_operand(rhs.right)
                new_rhs = BinOpRHS(rhs.op, new_lhs, new_right)

            var = instr.var
            k = counts.get(var, 0)
            new_name = f"{var}.{k}"
            counts[var] = k + 1
            current[var] = new_name

            ssa_program.append(Assign(new_name, new_rhs))
        else:
            new_operand = resolve_operand(instr.operand)
            ssa_program.append(Return(new_operand))

    return ssa_program


def pass2_simplify(
    ssa_program: list[Instruction],
) -> tuple[list[tuple[str, RHS]], Operand | None]:
    table: dict[str, TableValue] = {}
    kept: list[tuple[str, RHS]] = []
    return_operand: Operand | None = None

    def chase(name: str) -> str:
        while isinstance(table.get(name), Copy):
            name = table[name].source
        return name

    def substitute_operand(operand: Operand) -> Operand:
        if isinstance(operand, Lit):
            return operand
        val = table.get(operand.name)
        if isinstance(val, Const):
            return Lit(val.value)
        if isinstance(val, Copy):
            return VarRef(chase(operand.name))
        return operand

    for instr in ssa_program:
        if isinstance(instr, Assign):
            name = instr.var
            rhs = instr.rhs

            if isinstance(rhs, InputRHS):
                table[name] = Opaque()
                kept.append((name, InputRHS()))
            elif isinstance(rhs, LitRHS):
                table[name] = Const(rhs.value)
            else:
                left = substitute_operand(rhs.left)
                right = substitute_operand(rhs.right)

                if isinstance(left, Lit) and isinstance(right, Lit):
                    if rhs.op == '+':
                        result = left.value + right.value
                    elif rhs.op == '-':
                        result = left.value - right.value
                    else:
                        result = left.value * right.value
                    table[name] = Const(result)
                elif (
                    rhs.op == '-'
                    and isinstance(left, VarRef)
                    and isinstance(right, VarRef)
                    and left.name == right.name
                ):
                    table[name] = Const(0)
                elif rhs.op == '*' and (
                    (isinstance(left, Lit) and left.value == 0)
                    or (isinstance(right, Lit) and right.value == 0)
                ):
                    table[name] = Const(0)
                elif rhs.op == '*' and isinstance(left, Lit) and left.value == 1:
                    table[name] = Copy(right.name)
                elif rhs.op == '*' and isinstance(right, Lit) and right.value == 1:
                    table[name] = Copy(left.name)
                elif rhs.op == '+' and isinstance(right, Lit) and right.value == 0:
                    table[name] = Copy(left.name)
                elif rhs.op == '+' and isinstance(left, Lit) and left.value == 0:
                    table[name] = Copy(right.name)
                elif rhs.op == '-' and isinstance(right, Lit) and right.value == 0:
                    table[name] = Copy(left.name)
                else:
                    table[name] = Opaque()
                    kept.append((name, BinOpRHS(rhs.op, left, right)))
        else:
            return_operand = substitute_operand(instr.operand)

    return kept, return_operand


def pass3_dce(
    kept: list[tuple[str, RHS]], return_operand: Operand | None
) -> list[tuple[str, RHS]]:
    referenced: set[str] = set()

    if return_operand is not None and isinstance(return_operand, VarRef):
        referenced.add(return_operand.name)

    name_to_rhs: dict[str, RHS] = {name: rhs for name, rhs in kept}

    changed = True
    while changed:
        changed = False
        for name in list(referenced):
            if name in name_to_rhs:
                rhs = name_to_rhs[name]
                if isinstance(rhs, BinOpRHS):
                    for op in (rhs.left, rhs.right):
                        if isinstance(op, VarRef) and op.name not in referenced:
                            referenced.add(op.name)
                            changed = True

    surviving = [(name, rhs) for name, rhs in kept if name in referenced]
    return surviving


def format_operand(operand: Operand) -> str:
    if isinstance(operand, Lit):
        return str(operand.value)
    return operand.name


def format_rhs(rhs: RHS) -> str:
    if isinstance(rhs, InputRHS):
        return "input"
    if isinstance(rhs, LitRHS):
        return str(rhs.value)
    return f"{format_operand(rhs.left)} {rhs.op} {format_operand(rhs.right)}"


def main() -> None:
    ssa_program = pass1_ssa(program)
    kept, return_operand = pass2_simplify(ssa_program)
    surviving = pass3_dce(kept, return_operand)

    for name, rhs in surviving:
        print(f"{name} = {format_rhs(rhs)}")

    if return_operand is not None:
        print(f"return {format_operand(return_operand)}")


if __name__ == "__main__":
    main()

