    cents: int


@dataclass(frozen=True)
class Dispensing:
    change: int


State = Union[Idle, HasCredit, Dispensing]


# --- Event ---

@dataclass(frozen=True)
class Insert:
    cents: int


@dataclass(frozen=True)
class Select:
    code: int


@dataclass(frozen=True)
class DispenseDone:
    pass


Event = Union[Insert, Select, DispenseDone]


# --- Result ---

@dataclass(frozen=True)
class Ok:
    state: State


@dataclass(frozen=True)
class Err:
    reason: str


Result = Union[Ok, Err]


# --- Prices ---

PRICES = {1: 125, 2: 75, 3: 100}


def step(state: State, event: Event) -> Result:
    match (state, event):
        case (Idle(), Insert(n)) if n > 0:
            return Ok(HasCredit(n))
        case (Idle(), Insert(_)):
            return Err("invalid_amount")
        case (Idle(), Select(_)):
            return Err("no_credit")
        case (Idle(), DispenseDone()):
            return Err("not_dispensing")

        case (HasCredit(c), Insert(n)) if n > 0:
            return Ok(HasCredit(c + n))
        case (HasCredit(_), Insert(_)):
            return Err("invalid_amount")
        case (HasCredit(c), Select(code)):
            if code not in PRICES:
                return Err("unknown_item")
            elif c < PRICES[code]:
                return Err("insufficient_funds")
            else:
                return Ok(Dispensing(c - PRICES[code]))
        case (HasCredit(_), DispenseDone()):
            return Err("not_dispensing")

        case (Dispensing(_), Insert(_)):
            return Err("busy")
        case (Dispensing(_), Select(_)):
            return Err("busy")
        case (Dispensing(_), DispenseDone()):
            return Ok(Idle())


def format_result(result: Result) -> str:
    match result:
        case Ok(Idle()):
            return "ok: IDLE"
        case Ok(HasCredit(n)):
            return f"ok: CREDIT({n})"
        case Ok(Dispensing(ch)):
            return f"ok: DISPENSING({ch})"
        case Err(reason):
            return f"err: {reason}"


def main() -> None:
    events: list[Event] = [
        Insert(50),
        Select(1),
        Insert(100),
        Select(1),
        Insert(50),
        DispenseDone(),
        Select(2),
        Insert(100),
        Select(2),
        DispenseDone(),
