from dataclasses import dataclass
from typing import Union


@dataclass(frozen=True)
class Const:
    value: int


@dataclass(frozen=True)
class Var:
    name: str


@dataclass(frozen=True)
class Add:
    left: "Expr"
    right: "Expr"


@dataclass(frozen=True)
class Mul:
    left: "Expr"
    right: "Expr"


Expr = Union[Const, Var, Add, Mul]


def diff(expr: Expr, var: str) -> Expr:
    if isinstance(expr, Const):
        return Const(0)
    elif isinstance(expr, Var):
        if expr.name == var:
            return Const(1)
        else:
            return Const(0)
    elif isinstance(expr, Add):
        return Add(diff(expr.left, var), diff(expr.right, var))
    elif isinstance(expr, Mul):
        f = expr.left
        g = expr.right
        return Add(Mul(f, diff(g, var)), Mul(g, diff(f, var)))
    else:
        raise TypeError(f"Unknown expression type: {type(expr)}")


def simplify(expr: Expr) -> Expr:
    if isinstance(expr, (Const, Var)):
        return expr
    elif isinstance(expr, Add):
        left = simplify(expr.left)
        right = simplify(expr.right)
        if isinstance(left, Const) and left.value == 0:
            return right
        if isinstance(right, Const) and right.value == 0:
            return left
        return Add(left, right)
    elif isinstance(expr, Mul):
        left = simplify(expr.left)
        right = simplify(expr.right)
        if isinstance(left, Const) and left.value == 0:
            return Const(0)
        if isinstance(right, Const) and right.value == 0:
            return Const(0)
        if isinstance(left, Const) and left.value == 1:
            return right
        if isinstance(right, Const) and right.value == 1:
            return left
        return Mul(left, right)
    else:
        raise TypeError(f"Unknown expression type: {type(expr)}")


def showExpr(expr: Expr) -> str:
    if isinstance(expr, Const):
        return str(expr.value)
    elif isinstance(expr, Var):
        return expr.name
    elif isinstance(expr, Add):
        return f"({showExpr(expr.left)} + {showExpr(expr.right)})"
    elif isinstance(expr, Mul):
        return f"({showExpr(expr.left)} * {showExpr(expr.right)})"
    else:
        raise TypeError(f"Unknown expression type: {type(expr)}")


def main():
    expr = Add(
        Add(
            Mul(Var("x"), Var("x")),
            Mul(Const(3), Var("x")),
        ),
        Const(5),
    )

    derivative = diff(expr, "x")
    simplified = simplify(derivative)
    print(showExpr(simplified))


if __name__ == "__main__":
    main()

