module benchmark/solution

import std/io (println)
import std/option (Option, Some, None)

type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)

type Subst = [(string, Type)]

pure func findBinding(v: string, subst: Subst) -> Option[Type] =
  match subst {
    [] => None,
    (var, t) :: rest => if var == v then Some(t) else findBinding(v, rest)
  }

pure func applySubst(subst: Subst, t: Type) -> Type =
  match t {
    TVar(v) =>
      match findBinding(v, subst) {
        Some(bound) => applySubst(subst, bound),
        None => t
      },
    TInt => TInt,
    TBool => TBool,
    TFunc(arg, ret) => TFunc(applySubst(subst, arg), applySubst(subst, ret))
  }

pure func mapSubstValues(s2: Subst, s1: Subst) -> Subst =
  match s1 {
    [] => [],
    (v, t) :: rest => (v, applySubst(s2, t)) :: mapSubstValues(s2, rest)
  }

pure func compose(s2: Subst, s1: Subst) -> Subst =
  mapSubstValues(s2, s1) ++ s2

pure func bind(v: string, t: Type) -> Option[Subst] =
  match t {
    TVar(v2) => if v == v2 then Some([]) else Some([(v, t)]),
    _ => Some([(v, t)])
  }

pure func unify(t1: Type, t2: Type) -> Option[Subst] =
  match (t1, t2) {
    (TInt, TInt) => Some([]),
    (TBool, TBool) => Some([]),
    (TVar(a), t) => bind(a, t),
    (t, TVar(a)) => bind(a, t),
    (TFunc(a1, r1), TFunc(a2, r2)) =>
      match unify(a1, a2) {
        None => None,
        Some(s1) => {
          let r1' = applySubst(s1, r1);
          let r2' = applySubst(s1, r2);
          match unify(r1', r2') {
            None => None,
            Some(s2) => Some(compose(s2, s1))
          }
        }
      },
    _ => None
  }

pure func showType(t: Type) -> string =
  match t {
    TInt => "TInt",
    TBool => "TBool",
    TVar(v) => v,
    TFunc(_, _) => "TFunc(…)"
  }

func printBindings(subst: Subst) -> () ! {IO} =
  match subst {
    [] => (),
    (var, ty) :: rest => {
      println("${var} = ${showType(ty)}");
      printBindings(rest)
    }
  }

export func main() -> () ! {IO} {
  let tys1 = TFunc(TVar("a"), TInt);
  let tys2 = TFunc(TBool, TVar("b"));
  match unify(tys1, tys2) {
    Some(subst) => printBindings(subst),
    None => println("unification failed")
  }
}

