from dataclasses import dataclass
from typing import List, Tuple


@dataclass(frozen=True)
class Type:
    pass


@dataclass(frozen=True)
class TVar(Type):
    name: str


@dataclass(frozen=True)
class TInt(Type):
    pass


@dataclass(frozen=True)
class TBool(Type):
    pass


@dataclass(frozen=True)
class TFunc(Type):
    arg: Type
    result: Type


Substitution = List[Tuple[str, Type]]


class UnificationError(Exception):
    pass


def apply_subst(subst: Substitution, t: Type) -> Type:
    if isinstance(t, TVar):
        for name, ty in subst:
            if name == t.name:
                return apply_subst(subst, ty)
        return t
    if isinstance(t, TFunc):
        return TFunc(apply_subst(subst, t.arg), apply_subst(subst, t.result))
    return t


def unify(t1: Type, t2: Type) -> Substitution:
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    if isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    if isinstance(t1, TVar):
        return [(t1.name, t2)]
    if isinstance(t2, TVar):
        return [(t2.name, t1)]
    if isinstance(t1, TFunc) and isinstance(t2, TFunc):
        s1 = unify(t1.arg, t2.arg)
        s2 = unify(
            apply_subst(s1, t1.result),
            apply_subst(s1, t2.result),
        )
        return s1 + s2
    raise UnificationError(f"Cannot unify {t1} with {t2}")


def format_type(t: Type) -> str:
    if isinstance(t, TVar):
        return f"TVar({t.name})"
    if isinstance(t, TInt):
        return "TInt"
    if isinstance(t, TBool):
        return "TBool"
    if isinstance(t, TFunc):
        return f"TFunc({format_type(t.arg)}, {format_type(t.result)})"
    return str(t)


def main() -> None:
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))

    try:
        subst = unify(t1, t2)
        resolved = {name: apply_subst(subst, ty) for name, ty in subst}
        for name in ("a", "b"):
            if name in resolved:
                print(f"{name} = {format_type(resolved[name])}")
    except UnificationError as e:
        print(f"Unification failed: {e}")


if __name__ == "__main__":
    main()
